quests[37111] = { id = 37111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolfsausbildung: Der Garn", description = "In der letzten Prüfung für Euer Reittier geht es gegen eine der schrecklichsten Kreaturen dieses Landes.\n\nMan nennt sie die \"Garn\". Diese nachtschwarzen Wölfe sind doppelt so groß wie normale Wölfe und können einen Orc in Sekundenschnelle in Stücke reißen. Die Tiere dieser Gegend haben vollkommen zu Recht Angst vor ihnen.\n\nDa draußen streift ein einsamer Garn umher, der Nagrand zu seiner Heimat gemacht hat. Schwingt Euch auf Euren Wolf und schaltet ihn aus. Wenn Ihr beide überlebt, wird Euer Wolf für alle zukünftigen Aufgaben wahrhaft bereit sein.", sourceObjective = "Besiegt Malmkiefer vom Rücken Eures Ausbildungsknurrers aus.", completion = "Ein sehr wildes Tier, aber Ihr konntet es zähmen. Ich werde Euch niemals wieder unterschätzen. Euer Reittier wartet geduldig auf Eure Befehle, also ob es wüsste, was Ihr von ihm erwartet. Hier sind Eure Zügel. Möge Euch Euer Gefährte immer begleiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[37112] = { id = 37112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhe und Entspannung", description = "Jeder Abenteurer sollte ausruhen, wenn ihn die Erschöpfung überkommt – und es gibt keinen besseren Platz für Ruhe und Entspannung als das Gasthaus \"Zur Höhle des Löwen\"!\n\nGastwirt Farley, der Inhaber der \"Höhle des Löwen\", ist mein bester Freund. Wenn Ihr ihm sagt, dass ich Euch geschickt habe, dann gewährt er Euch vielleicht einen Spezialrabatt auf Essen und Trinken.\n\nDas Gasthaus \"Zur Höhle des Löwen\" findet Ihr, wenn Ihr auf der Straße nach Süden reist – Ihr könnt es nicht verfehlen!", sourceObjective = "Sprecht im Gasthaus \"Zur Höhle des Löwen\" mit Gastwirt Farley.", completion = "Ruhe und Entspannung für die Müden und Frierenden – das ist unser Leitspruch! Bitte setzt Euch ans Feuer und wärmt Eure müden Knochen.\n\nMöchtet Ihr von unseren erlesenen Speisen und Getränken kosten?", sourceObjectiveStatus = "unverified-source-field" }
quests[37113] = { id = 37113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thisalee Krähe", sourceObjective = "Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[37114] = { id = 37114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Choluna", sourceObjective = "Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[37119] = { id = 37119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anhänger anwerben", description = "Die Gaststätte ist der perfekte Ort für Abenteurer, um sich auf ihren Reisen auszuruhen. Man kann sie dort auch auf ein paar Getränke einladen und sie dabei dazu bringen, sich unserer Sache anzuschließen.\n\nGeht meine Auswahlliste durch und dann sehen wir, ob wir einen neuen Rekruten anwerben können. Ihr bekommt von mir einen Finderlohn für Eure Bemühungen.", sourceObjective = "Rekrutiert einen Anhänger von Lysa Serion im Mondsturzgasthaus.", completion = "Ach, bin ich froh, dass Ihr einen guten Kandidaten für uns gewinnen konntet!\n\nIch werde noch weitere für Euch suchen. Schaut wöchentlich bei mir vorbei, um Euch meine neueste Auswahl anzusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37120] = { id = 37120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunspring POI Tracking Quest" }
quests[37121] = { id = 37121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die schwarze Klaue", description = "Wie Ihr wahrscheinlich sehen könnt, befindet sich hinter mir eine riesige schwarze Klaue. Wir haben sie bei der Jagd auf neue zähmbare Tiere gefunden. Die Tiere scheinen große Angst vor ihr zu haben, vielleicht hat das Biest, zu dem sie gehört, sie vorher gejagt.", sourceObjective = "Fragt Fanny Feuerbart nach der schwarzen Klaue von Sethe.", completion = "Wie ich bereits sagte, hat die Klaue eine seltsame Wirkung auf die Reittiere, die wir hier haben. Wenn Ihr sie bei der Ausbildung eines zukünftigen Reittiers dabei habt, ist Euer Reittier VIEL verwundbarer.\n\nSolltet Ihr der Meinung sein, dass die Ausbildung nicht hart genug ist, könnt Ihr Euch selbst fordern.\n\nIch habe eine ziemlich saftige Belohnung für jemanden, der das schafft!", sourceObjectiveStatus = "unverified-source-field" }
quests[37122] = { id = 37122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubtierzähne", description = "Diese Halskette hat einer der Orcjäger verloren, über die wir gestolpert sind, als wir mit den Tieren zwecks deren Ausbildung unterwegs waren. Ich habe Tiere noch nie so heftig auf irgendetwas reagieren sehen.", sourceObjective = "Fragt Fanny Feuerbart nach der Garnzahnhalskette.", completion = "In meinem ganzen Leben habe ich die Tiere noch nie so durchdrehen sehen, wie an dem Tag, an dem wir das Ding in den Stall mitbrachten.\n\nSolltet Ihr der Meinung sein, dass die Ausbildung nicht hart genug ist, dann tragt es bei Euch. Eure Ausbildungsreittiere werden NOCH verwundbarer sein.\n\nSeid vorsichtig! Ich würde demjenigen einen Preis geben, der jedes Tier mit diesem Artefakt zähmen könnte, aber ich möchte nicht erleben, dass Ihr dabei draufgeht!", sourceObjectiveStatus = "unverified-source-field" }
quests[37123] = { id = 37123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die schwarze Klaue", description = "Ihr habt wahrscheinlich diese riesige schwarze Klaue in unserem Vorratsstapel bemerkt. Wir haben sie während der Jagd auf neue zähmbare Tiere gefunden. Die Tiere scheinen große Angst vor ihr zu haben, vielleicht hat das Biest, zu dem sie gehört, sie vorher gejagt.", sourceObjective = "Fragt die Weise Paluna nach der schwarzen Klaue von Sethe.", completion = "Die Klaue hat eine seltsame Wirkung auf unsere Reittiere. Wenn Ihr sie bei der Ausbildung eines zukünftigen Reittiers dabei habt, ist Euer Reittier VIEL verwundbarer.\n\nSolltet Ihr der Meinung sein, dass die Ausbildung nicht hart genug ist, könnt Ihr Euch selbst fordern, indem ihr sie bei Euch tragt.\n\nIch denke, die Tiere Draenors damit zu überwältigen, wäre sicherlich eine Belohnung wert.", sourceObjectiveStatus = "unverified-source-field" }
quests[37124] = { id = 37124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubtierzähne", description = "Diese Halskette hat einer der Orcjäger verloren, über die wir gestolpert sind, als wir mit den Tieren zwecks deren Ausbildung unterwegs waren. Ich habe Tiere noch nie so heftig auf irgendetwas reagieren sehen.", sourceObjective = "Fragt die Weise Paluna nach der Garnzahnhalskette.", completion = "In meiner ganzen Zeit als Weiser habe ich die Tiere noch nie so durchdrehen sehen, wie an dem Tag, an dem wir diese Halskette in den Stall mitbrachten.\n\nSolltet Ihr der Meinung sein, dass die Ausbildung nicht hart genug ist, dann tragt sie bei Euch. Eure Ausbildungsreittiere werden NOCH verwundbarer sein.\n\nSeid vorsichtig! Ich würde demjenigen einen Preis geben, der jedes Tier mit diesem Artefakt zähmen könnte, aber ich möchte nicht erleben, dass Ihr dabei draufgeht!", sourceObjectiveStatus = "unverified-source-field" }
quests[37125] = { id = 37125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein seltener Fund", progress = "Hin und wieder macht ein Archäologe einen seltenen Fund... ein Artefakt, das über die Zeitalter hinweg gut erhalten geblieben ist, als ob es aus einer Zeitmaschine gefallen wäre.\n\nWenn ich nur darüber nachdenke, wie aufregend es ist, einen solchen Fund zu machen, bin ich ganz aufgewühlt... derartige Relikte sind ein Vermögen wert!", completion = "Toller Fund! Dieses Relikt wird in der privaten Sammlung von jemandem sicher willkommen sein!" }
quests[37126] = { id = 37126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Oger ohne sein Schwert...", description = "Bevor man mich nach Gorgrond brachte, war ich an der Zerschlagenen Anhöhe in Nagrand stationiert, um dort die Ordnung zu wahren. Wesir Dar'gud ließ mich mein Lieblingsschwert nicht mitnehmen. Er sagte, ich würde es dort, wo ich hinginge, nicht brauchen.\n\nIch will es zurück, Kommandant, und gemeinsam sind wir stark genug, um es Dar'guds blutiger Leiche zu entwenden.\n\nDas würde mir sehr viel bedeuten. Ein Oger ohne sein Schwert ist kein Oger.", sourceObjective = "Holt Tormmoks Lieblingsschwert von Wesir Dar'gud auf der Zerschlagenen Anhöhe in Nagrand.", progress = "Ich will mein Schwert mehr, als ich Euch sagen kann, Kommandant.", completion = "Ja... das ist es.\n\nKommandant, jetzt, wo ich mein Schwert zurückhabe, werde ich Eure Feinde zerstückeln wie nie zuvor.", sourceObjectiveStatus = "unverified-source-field" }
quests[37127] = { id = 37127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Licht des Exodus", description = "Mein Großvater hat mir immer Geschichten über einen mächtigen Kristall erzählt, der aus dem Licht geschaffen worden war und denjenigen, die ihn zum Guten einsetzen wollten, Macht verlieh. Er nannte ihn das Licht des Exodus.\n\nIch habe ihm das nie abgenommen... bis jetzt.\n\nEure Späher haben einen Kristall gefunden, auf den diese Beschreibung genau passt. Ein furchtbarer Dämon hat ihn an sich gebracht und verdirbt ihn beim Leuchtfeuer der Sha'tar in Shattrath.\n\nWir müssen uns beeilen!", sourceObjective = "Besorgt das Licht des Exodus von Botschafter Höllenschlund beim Leuchtfeuer der Sha'tar in Shattrath in Talador.", progress = "Wenn das Licht des Exodus nur halb so mächtig ist, wie mein Großvater mir gesagt hat, dann dürfen wir nicht zulassen, dass es in die Hände der Legion fällt.", completion = "Es ist so wunderschön...\n\nOh, Kommandant, tausend Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[37128] = { id = 37128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschwerden schlichten", description = "Unsere Späher haben einen mächtigen Draeneikristall entdeckt, der von Botschafter Höllenschlund beim Leuchtfeuer der Sha'tar in Shattrath verderbt wird. Die Draenei nennen ihn das Licht des Exodus.\n\nKommandant, ich würde Euch gern bei dieser Mission begleiten. Höllenschlund hat meinen Bruder in der Scherbenwelt getötet... Das ist eine persönliche Angelegenheit.", sourceObjective = "Besorgt das Licht des Exodus von Botschafter Höllenschlund beim Leuchtfeuer der Sha'tar in Shattrath in Talador.", progress = "Wir können nicht zulassen, dass die Legion einen Vorteil erhält.", completion = "Es ist vollbracht. Die Legion hat einen schweren Schlag erlitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[37129] = { id = 37129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungebetene Erinnerungen", description = "Die Botani in der Immergrünen Wildnis woll'n irgendeine üble Magie einsetzen, um diese Pflanzen... naja... im Grunde Pflanzenzombies zu erschaffen.\n\nIch hab' gesehen, was mit Armeen geistloser Sklaven passiert. Der Lichkönig...\n\n<Delvar schließt die Augen.>\n\nEgal. Wir können das nicht weiter ausufern lass'n. Ich hab' von 'nem ganz Widerlichen gehört, den sie grade erschaffen haben... Lasst ihn uns töten und herausfinden, was ihn antreibt.", sourceObjective = "Besorgt die Überreste eines befallenen Orcs von Akanthus in der Immergrünen Wildnis in Gorgrond.", progress = "Auf dieser Welt wird's keine Zombies geben, ob Pflanzen oder sonstwelche, solange der alte Delvar noch was zu sagen hat.", completion = "Ich werd' mir dieses... Ding ganz genau anseh'n. Was in Nordend passiert ist, darf nicht nochmal gescheh'n...", sourceObjectiveStatus = "unverified-source-field" }
quests[37130] = { id = 37130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunspring POI Tracking Quest" }
quests[37131] = { id = 37131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sorge der Dunklen Fürstin", description = "Die Botani in der Immergrünen Wildnis töten jeden, der dumm genug ist, sich ihren Blüten zu nähern. Dann machen sie die Leichen zu geistlosen Soldaten.\n\nDas erinnert viel zu sehr an die Geißel... was auch die Dunkle Fürstin bemerkt hat. Sie hat eine ganz besondere Mission für uns, Kommandant.\n\nEs gibt eine besonders große, befallene Kreatur, die vor Kurzem wiedererweckt wurde. Wir müssen sie vernichten und ihre Überreste bergen.", sourceObjective = "Besorgt die Überreste eines befallenen Orcs von Akanthus in der Immergrünen Wildnis in Gorgrond.", progress = "Ich versichere Euch, Kommandant, die Dunkle Fürstin will nur das Beste für die Horde. Wir müssen diese Botani sofort aufhalten.", completion = "Danke, Kommandant. Die Dunkle Fürstin wird das sehr zu schätzen wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37132] = { id = 37132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunspring POI Tracking Quest" }
