quests[37136] = { id = 37136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunspring POI Tracking Quest" }
quests[37137] = { id = 37137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahrsagen oder versagen", description = "Es gibt noch andere, die sich die Schatten zunutze machen. Ihr kennt sie, Kommandant... die Schattenmondorcs.\n\nSie sind kurz davor, ihre Fertigkeit zu vervollkommnen... Sie rufen die Schatten jenseits dieser Gefilde an...\n\nMich dürstet nach ihrer Macht. Sie haben einen unter sich, der einen besonders interessanten Stab besitzt... Wir sollten ihn für uns beanspruchen.", sourceObjective = "Holt Urnas Tiefenstab von Urna Dunkelgrund aus der Schattenmondenklave im Schattenmondtal.", progress = "Die Feinde auslöschen und gleichzeitig große Macht erlangen... Mein Volk hat dafür ein Sprichwort: Zwei Orcs mit einer Klappe schlagen.", completion = "Ja... ja... das wird reichen. Wir können das verwenden, um große Dinge zu tun.\n\nIch danke Euch, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[37140] = { id = 37140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leorajhs Gebetsperlen", description = "Als Leorajh Schamane wurde, gab der Rudelführer ihm Gebetsperlen. Gebetsperlen helfen Leorajh, die Elemente zu hören.\n\nEines Tages griffen Vogelmänner an und stahlen Gebetsperlen. Sie haben sie nach Skettis gebracht.\n\nKönnt Ihr Leorajh helfen, die Gebetsperlen zurückzubekommen?", sourceObjective = "Nehmt Leorajhs Gebetsperlen Kirox dem Windtänzer in Skettis ab.", progress = "Die Elemente sprechen nicht mehr so zu Leorajh wie früher.", completion = "Ich danke Euch! Jetzt sprechen die Elemente wieder zu Leorajh.", sourceObjectiveStatus = "unverified-source-field" }
quests[37141] = { id = 37141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krallenpriester Ishaal", sourceObjective = "Meine Bestimmung als Krallenpriester hat sich erfüllt. Auch wenn vielleicht Iskar und Zellek glauben, dass ich ein Narr bin, weil ich die heiligen Riten geändert habe.\n\nAber ich benötige ihre Zustimmung nicht. Ich bin es leid, mich in den Schatten zu verbergen.\n\nLasst mich für Euch kämpfen. Ich möchte diese Welt verbessern, bevor ich sie verlassen muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[37142] = { id = 37142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogervorfahren", description = "Lunk mag nicht kämpfen, will aber lernen. Helft Ihr Lunk lernen?\n\nFindet Lunks Vorfahren. Lunk hat viele Fragen. Woher kommt Lunk? Warum LunkLunk?\n\nLunk bleibt hier. Kleine Oger fies. Große Oger noch fieser.", sourceObjective = "Beschafft einen Ogerstammbaum aus der Blutschlägermine.", progress = "Wie kann LunkLunk sein, wenn Lunk nicht weiß, was Lunk ist?", completion = "Lunk weiß, Ihr töten viele Oger dafür und Lunk sehr traurig darüber. Aber Lunk trotzdem dankbar.\n\nHalt, das nicht Keule von Familie Lunk...", sourceObjectiveStatus = "unverified-source-field" }
quests[37144] = { id = 37144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klauenwache Kurekk", sourceObjective = "Ihr habt viel für uns getan. Was könnte ich anderes bieten außer meiner Klinge?\n\nKrallenkönig, lasst mich für Euch kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37145] = { id = 37145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Budds Schachzug", description = "Keine Ahnung, wie ich hierher gekommen bin, ich weiß aber aus zuverlässiger Quelle, dass es eine ganze Insel gibt, die aus glänzenden Dingen besteht und dass sie gleich vor der Küste liegt.\n\nWir müssen einfach nur ins Wasser springen und hinschwimmen, unsere Taschen vollstopfen und dann wieder zurückschwimmen! Ich werde mich noch ausruhen und ein paar Dehnübungen machen, bevor ich losschwimme.\n\nVersucht bloß nicht, mich aufzuhalten!", sourceObjective = "Holt in den Eisendocks ein verlockend glänzendes Etwas.", progress = "Wie?", completion = "Oh... das ist ja... das glänzt doch hübsch, findet Ihr nicht auch? Ich glaube... ich bleibe einfach ein Weilchen hier sitzen.\n\n<Budd lächelt zufrieden.>", sourceObjectiveStatus = "unverified-source-field" }
quests[37146] = { id = 37146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apport", description = "DAS nenne ich mal ein wildes Land, das meines Heldentums würdig ist!\n\nAch hallo, ich habe euch gar nicht da stehen und mich anstarren gesehen. Vielleicht ist Euch aufgefallen, dass es sich bei jedem Teil meiner Rüstung um ein uraltes Relikt handelt, das von der Zeit vergessen wurde.\n\nWie Ihr richtig gefolgert habt, bleibt einem Abenteurer meines Formats nicht die Zeit, die niederen Aufgaben abzuschließen, die man mir täglich gibt. Ich muss hierbleiben und laut in den Handelsdistrikt hineinrufen, damit andere mein Heldentum erleben und von ihm inspiriert werden.\n\nHeute brauche ich eine Alptraumglocke. Seid so nett und beschafft mir eine.", sourceObjective = "Besorgt eine Alptraumglocke aus Auchindoun.", progress = "Was wollt Ihr?", completion = "Wie ich sehe, habt Ihr diese niedere Aufgabe vortrefflich bewältigt, fast so, als wäre es Eure Bestimmung, so etwas zu erleben. Ach Schicksal, was hast du wohl als Nächstes für mich geplant?", sourceObjectiveStatus = "unverified-source-field" }
quests[37147] = { id = 37147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Himmelstänzer", description = "Seid gegrüßt, {name}. Vielen Dank für Eure Gastfreundschaft.\n\nDie Shado-Pan schicken mehrere Krieger, um im Kampf gegen die Eiserne Horde so gut zu helfen, wie wir können. Wir sind jedoch wenige und sie sind viele.\n\nDie Arakkoa im Süden sind ebenso schön wie tödlich. Sie scheinen leichter als die Luft zu sein und greifen an wie in einem tödlicher Tanz, huschen von einem Gegner zum nächsten.\n\nDer Wind ist auf ihrer Seite, so wie die vier Winde meinen eigenen Verbündeten die Schritte erleichtern. Wenn Ihr könnt, bringt mir eine Probe ihres Windes. Das wird uns sicher helfen.", sourceObjective = "Holt einen Windsturm in der Flasche von der Himmelsnadel.", progress = "Habt Ihr den fünften Wind gefunden?", completion = "Ich werde ihn unverzüglich zu den Shado-Pan bringen. Möge Euch das Glück hold sein. Wir werden Eure Hilfe wieder benötigen, wenn der Wind abflaut.", sourceObjectiveStatus = "unverified-source-field" }
quests[37148] = { id = 37148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oralius' Abenteuer", description = "Ich und Winky auf neuen Abenteuern! So sollte das Leben immer sein, sag ich Euch. Man muss keine brennende Luft atmen, und es gibt reichlich Oger zu töten!\n\n<Oralius reibt sich den Bauch.>\n\nWir haben allerdings ein leichtes Chaos an der Schwarzfelsspitze hinterlassen. Ein ganzer Haufen dieser eisengepanzerten Orcs und einige Protodrachen sind aus dem Süden einmarschiert und haben sie übernommen.\n\nDer alte Winky konnte die Schuld nicht auf sich nehmen. Ist allein zurückgegangen, um sie aufzuhalten!\n\nOder... um ihnen BEIZUTRETEN! Winky, du verräterischer Orcsohn. Wir müssen ihn aufhalten!", sourceObjective = "Fangt an der Oberen Schwarzfelsspitze eine Flammenfliege der Spitze.", progress = "Habt Ihr ihn aufgehalten?", completion = "Ein guter Plan. Winky mochte diese Flammenfliegen schon immer. Wenn wir genug davon sammeln, können wir ihn vielleicht davon überzeugen, zurückzukommen!\n\nVielleicht... äh... solltet Ihr das hier eine Weile behalten, hm?", sourceObjectiveStatus = "unverified-source-field" }
quests[37149] = { id = 37149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Leerentor", description = "Mein 'Meister' ist nicht gerade der Hellste, aber Ihr seht so aus, als hättet Ihr ein bisschen Grips in Eurem unförmigen Schädel.\n\nAlso hört zu, der Wirbelnde Nether ist ein chaotischer Abgrund, dort laufen die Dinge anders. Ich spüre immer wieder Erschütterungen und das bedeutet nichts Gutes, für niemanden von uns.\n\nIrgendetwas geht vor sich hier in Draenor und das verursacht Wellen im Nether. Versucht erst gar nicht, das zu verstehen, Ihr würdet Euch nur den Kopf zerbrechen.\n\nEigentlich ist es ganz einfach: Bringt mir einen Schlüssel zum Leerentor, vielleicht kann ich dann das Schlimmste verhindern.", sourceObjective = "Findet einen Schlüssel zum Leerentor in der Schattenmondgrabstätte.", progress = "Ihr seid Euch hoffentlich bewusst, dass jede Sekunde, die wir mit leeren Worten verschwenden, uns dem Verderben näher bringt.", completion = "Ausgezeichnet, hier nehmt dies als Belohnung für Eure Mühen.\n\nIch muss jetzt los, um mal wieder die Welt zu retten. Das wird langsam zur Gewohnheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[37150] = { id = 37150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Vögel", description = "Hallo! Habt Ihr schon mal ein frisch geschlüpftes Pfauenküken gehalten?\n\n<Mylune ergreift Eure Hände ohne Vorwarnung und legt ein kleines zwitscherndes Vögelchen hinein.>\n\nSo klein und leicht und flaumig. Als würde man eine piepende kleine WOLKE mit Schnabel halten! Es ist so niedlich, da kann man nicht anders, als es zu umarmen und zu knuddeln und vorgekautes Essen in seinen klitzekleinen Mund zu stopfen.\n\n{name}, die Pflanzenwesen des Immergrünen Flors machen die Pfauenküken zu Monstern, bevor sie aufwachsen und zu wunderschönen Schwänen werden können. Oder was auch immer sie werden, wenn sie aufwachsen. Bitte helft ihnen!", sourceObjective = "Sucht ein winziges Pfauenküken im Immergrünen Flor.", progress = "Habt Ihr ein Pfauenküken gerettet? Sie haben nur uns, und diese schrecklichen Pflanzenwesen behandeln sie grausam!\n\n<Mylunes Stimme sinkt plötzlich um zwei Oktaven, was Euch kalte Schauer den Rücken hinablaufen lässt.>\n\nAbsolut grausam.", completion = "<Mylune hebt den klitzekleinen Vogel vorsichtig zu ihrem Gesicht hinauf und schmiegt sich an ihn. Er krabbelt auf ihre Schulter und verschwindet in das Nest aus grünem Haar. Einen Moment später entspringt ein wunderschöner Fächer aus bunten Schwanzfedern ihrem Kopf.>\n\n<Mylunes große blaue Augen füllen sich mit Tränen und ihr Mund bleibt voller Bewunderung offen stehen. Ihr habt die Dryade SEHR glücklich gemacht.>", sourceObjectiveStatus = "unverified-source-field" }
quests[37151] = { id = 37151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalter Stahl", description = "Ihr wollt wissen, was ich will? Dasselbe wie jeder, der durch das Portal geschritten ist. Jeder Soldat, der einer Welt entflohen ist, die ihn nicht verstehen konnte, ihn nicht gebraucht hat. Ich will, dass diese Welt uns so sehr liebt, wie wir sie lieben.\n\nDoch wir gehören dort einfach nicht hin, nicht mehr. Der Krieg ist ein Teil von uns, und wir können nicht mehr zurückkehren. Für alle dort sind wir entbehrlich.\n\nDas Einzige, was mich jetzt noch aufmuntert, ist das Gefühl einer Kanone aus kaltem Stahl in meinen Händen – direkt auf den Feind gerichtet.\n\n<Keeshan starrt in seinen Bierkrug.>", sourceObjective = "Findet eine Eiserne Autokanone im Grimmgleisdepot.", progress = "Lasst mich in Ruhe.", completion = "Ja, die wird ihren Zweck erfüllen. Ich werde zwar bald keine Munition mehr haben, aber wenigstens habe ich eine Weile lang einen Grund zu leben.\n\nDa, nehmt. Ihr werdet sie dringender brauchen als ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[37152] = { id = 37152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cros Rache", description = "HA! Die Obstverkäuferin war gerissen, aber ich, Cro Dickfädel bin NOCH gerissener. Ich bin zurück in die Vergangenheit gereist, um die Ogerarmee zu besiegen, bevor die Obstverkäuferin sie gegen mich wenden kann!\n\nBringt mit den Kopf eines großen, kräftigen Ogers aus der alten Blutschlägermine, dann werde ich die Obstverkäuferin bezwingen, bevor ein einziger Apfel gewachsen ist!\n\nHÖRT IHR MICH, OBSTVERKÄUFERIN? ICH WERDE SIEGEN!", sourceObjective = "Besorgt einen riesigen Ogerkopf aus der Blutschlägermine.", progress = "DIE OBSTVERKÄUFERIN HAT KEINE CHANCE!", completion = "Rache ist ja so süß. Wie ein Apfel.\n\nNehmt ihn. Auf dass all Euer Obst ZERQUETSCHT WIRD WIE EURE FEINDE.", sourceObjectiveStatus = "unverified-source-field" }
quests[37153] = { id = 37153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeitverlorene Wikinger", description = "Oi, da habe ich es gerade noch rausgeschafft!\n\nWir wollten nur helfen und sind durchs Portal, und bevor wir wussten, was uns geschah, waren wir Gefangene in der Blutschlägermine. Es war brutal! Wir waren tagelang angekettet und mussten im Dreck liegen.\n\nUnd sie haben meinen SCHILD genommen!", sourceObjective = "Holt Olafs Schild aus der Blutschlägermine.", progress = "<Olaf schluchzt.>", completion = "Oi, ist zwar verdammt schmutzig, aber das ist er! Hier, für Euch. Habt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[37154] = { id = 37154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Heilmittel gegen den Tod", description = "Seid gegrüßt und habt dank für die Wärme dieses Gasthauses und Eure Gastfreundlichkeit.\n\nWie Ihr sehen könnt, leide ich noch immer am Übel des Todes. Meine Studien in Azeroth und Nordend waren erfolglos, und all meine Ansätze sind im Nichts verlaufen.\n\nIch bin in der Hoffnung, auf irgendeine neue Idee zu stoßen, nach Draenor gekommen. Meine erste Pilgerreise führt mich nach Auchindoun, einem Haus, in dem Seelen Ruhe finden.\n\nFalls Ihr Euch selbst dorthin begeben solltet, lasst mich wissen, ob Ihr auf etwas Interessantes stoßt.", sourceObjective = "Besorgt ein Seelenflechtgefäß in Auchindoun.", progress = "Habt Ihr etwas gefunden?", completion = "Das... das könnte mir helfen. Ich muss bald zur Kapelle des Hoffnungsvollen Lichts zurückkehren, habt meinen Dank.\n\nIch brauche diese Vorräte nicht mehr. Sie gehören Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[37155] = { id = 37155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Messingkompass", description = "Seid gegrüßt, Kommandant. Ich wurde vom Kapitän persönlich auf diese Mission ausgesandt.\n\nEgal, auf welchem Schiff man sich auf Azeroths Meeren befindet, sofern ein einziger Orc an Bord ist, hört man Seemannslieder über ein Gerät, dass die weiten, rauen Ozeane von Draenor navigierbar macht. Die Orcs nutzten es, um selbst in den wechselhaftesten Stürmen die wahre Bugrichtung im Auge zu behalten.\n\nVielleicht handelt es sich dabei ja nur um Seemansgarn, aber für diese eine Chance, eine solche Beute zu finden, ist der Kapitän bereit, sich von einigen seiner schönsten Schätze zu trennen.", sourceObjective = "Findet den Messingkompass an den Eisendocks.", progress = "Habt Ihr den Kompass gefunden?", completion = "Das könnte tatsächlich sein, wonach wir gesucht haben. Hier ist Euer Schatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[37156] = { id = 37156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seelenschnitter", description = "Seht mich nicht an! Für wen haltet Ihr Euch denn eigentlich?\n\nWir sind auf derselben Seite, wisst Ihr. Die Totenbeschwörer hier, wir müssen sie töten. Absolut alle.\n\nFindet Ihr nicht?\n\nNatürlich tut Ihr das, und Ihr könnt mir dabei helfen, dieses Ziel zu erreichen. Findet die Seelenschnittklinge in der Hütte, in der sich die Totenbeschwörer wie Ratten eingenistet haben. Sie hat... spezielle Eigenschaften... die uns im Kampf gegen die Untoten helfen werden.", sourceObjective = "Beschafft eine Seelenschnittklinge aus Auchindoun.", progress = "Habt Ihr die Klinge gefunden?", completion = "Ausgezeichnet, wirklich ausgezeichnet.\n\nIch werde sie bald abgenutzt haben, und sie kann aufgrund ihrer einzigartigen Eigenschaften nicht repariert werden. Also erwartet, bald wieder von mir zu hören.", sourceObjectiveStatus = "unverified-source-field" }
quests[37157] = { id = 37157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie schrecklich ungeschickt... von Euch", description = "Nach so vielen Jahren, in denen ich immer wieder durch unbekannte Mächte erweckt worden und als Geist aufgewacht bin, sehne ich mich nach bestimmten Dingen. Am sehnlichsten wünsche ich mir jedoch die tröstliche und samtige Dunkelheit des Todes.\n\nAber ich würde mich auch schon damit zufrieden geben, wenn jemand die Vielzahl der Schleifspuren entfernen würde, die von den wundervollen Kameraden des Kommandanten im gesamten Speisesaal verursacht wurden, obschon sie nur einen bedauerlich kurzen Aufenthalt in Karazhan genossen haben, während dessen sie kaum genug Zeit hatten, nahezu irreparable Schäden am unbezahlbaren Mobiliar zu hinterlassen.", sourceObjective = "Besorgt ein Fass schrecklich säurehaltiger Lösung von den Eisendocks.", progress = "War der Kommandant erfolgreich?", completion = "Kommandant, ich stehe auf ewig in Eurer Schuld für Euer unzweifelhaft selbstloses Eintreten in dieser dringlichen Angelegenheit.\n\nEs dürften zwar noch mehr dieser Fässer existieren, aber unter diesen Umständen muss dieses eine Fass Genüge tun, da ich ja davon ausgehen muss, dass Ihr Euch als Kommandant um wichtigere Belange kümmern müsst, die das ganze Land betreffen, und keine Zeit habt, den Dreck aufzuräumen, den Eure Euch treu folgenden Gefährten so flächendeckend in der ganzen Gegend verteilt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[37158] = { id = 37158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das glorreiche Glühen", description = "Ich bin nicht gekommen, um zu kämpfen, dafür habe ich schon zu viele sterben sehen. Ich habe schon so viele mit meinen eigenen Händen getötet.\n\nIch bin gekommen, um das Licht und Erlösung zu finden.\n\nDie Arakkoa dieses Landes verehren die Sonne, so wie auch ich. Doch sie sind ein brutales, eigenbrötlerisches und dekadentes Volk, das ihr eine andere Bedeutung entnimmt als meine eigenen Leute. Das bereitet mir Sorgen.\n\nBringt mir einen ihrer Sonnenkristalle. Ich möchte dieses Licht sehen.", sourceObjective = "Beschafft einen Sonnenkristall in Himmelsnadel.", progress = "Habt Ihr den Kristall gefunden?", completion = "Die Sonne, ich kann sie sehen. Sie ist so hell.\n\nIch... möchte alleine sein. Nehmt dies mit meinem Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[37159] = { id = 37159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avianas Anfrage", description = "Die Arakkoa sind Wesen des Himmels und leben daher im Reich der großen Aviana.\n\nIch wurde ausgesandt, eine Feder zu beschaffen, damit wir in der Sprache des Windes mit ihnen verhandeln können. Wir werden ihnen ein Friedensangebot machen und einen Platz auf dem großen Ast bieten.\n\nWürdet Ihr uns bei dieser Aufgabe behilflich sein? Die Feder muss von einem adligen Arakkoa stammen. Ihr könnt sie an einem Ort namens Himmelsnadel finden.", sourceObjective = "Sammelt makelloses Gefieder in Himmelsnadel.", progress = "Habt Ihr die Feder mitgebracht?", completion = "Habt meinen Dank, {name}. Aviana wird erfreut sein, und vielleicht werden wir auch Euch helfen können.\n\nAviana hat es für richtig erachtet, Euch hiermit zu segnen, geht also gut damit um.", sourceObjectiveStatus = "unverified-source-field" }
quests[37160] = { id = 37160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spalter!", description = "Ich, Gamon, bin durch das Dunkle Portal gekommen, um viele Orcschädel zu spalten. Doch meine Waffe konnte meiner Wut nicht standhalten und ist stumpf und schartig.\n\nFindet mir eine neue Waffe: eine, die sich dafür eignet, Höllschreis Glieder zu entfernen.", sourceObjective = "Findet einen eisernen Gliedmaßenspalter im Grimmgleisdepot.", progress = "Was?", completion = "Die Klinge gefällt mir. Damit werde ich viele Glieder abhacken können. Hier, für Euch. Etwas, das Euch an mich erinnern wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[37161] = { id = 37161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Familientraditionen", description = "Er ist damit weggerannt! Was kann ich nur tun, was soll ich TUN?\n\nMein Sohn, und mein Messer, sind zur Schwarzfelsspitze aufgebrochen. Nun, mein Messer ist wohl eher mitgenommen worden. Darum geht es nicht!\n\nIhr müsst es zurückbringen! Ja, das Messer! Ihr müsst das Messer zurückbringen!\n\nGeht! Los! Hört auf zu schwatzen!", sourceObjective = "Findet Pips verbesserten Kürschner an der Schwarzfelsspitze.", progress = "Wo ist mein Messer?", completion = "Ihr habt es gefunden! Es ist in Sicherheit! Ich hatte mir schon solche Sorgen gemacht! Hier, nehmt das!", sourceObjectiveStatus = "unverified-source-field" }
quests[37162] = { id = 37162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Damen und Drachen", description = "Seid gegrüßt, <Knappe/Schildmaid> {name}! Vergebt meinen Lippen, dass sie so schwerwiegende Nachrichten überbringen. Drachen haben sich in den heiligen Hallen der Schwarzfelsspitze niedergelassen!\n\nDiese großen Wyrm halten eine verzweifelte Dame in ihren schuppigen Greifern gefangen. Man sagt, ihr Name ist Zaela. Solch ein wunderschöner Name!\n\nAls <mein Knappe/meine Schildmaid> ist es Eure lichtgegebene Aufgabe, Euch zu der Spitze durchzuschlagen und Beweise für diese Drachen zu beschaffen, damit ich mein Heldentum nicht für eine drachenlose Quest verschwende.", sourceObjective = "Sammelt eine abgestoßene Protodrachenklaue.", progress = "Habt Ihr Beweise für Drachen gefunden?", completion = "Das sind wahrlich schreckliche Beweise! Ich werde mich gleich dorthin begeben und mindestens zwanzig der großen Bestien besiegen.\n\nFür Doloria!", sourceObjectiveStatus = "unverified-source-field" }
quests[37163] = { id = 37163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Schatten", description = "Obwohl der Lichkönig besiegt wurde, ist es uns immer noch nicht gelungen, tiefer in die Geheimnisse des Frostthrons einzudringen. Wir sind nicht weiter als zu Zeiten des Argentumturniers, als wir uns nutzlosen Wettkämpfen hingaben. Bolvar ist weiterhin ein Gefangener des Frostthrons.\n\nVielleicht finden wir hier etwas, das uns hilft. Wie Ihr vielleicht wisst, war Ner'zhul nicht immer der Lichkönig. Einst war er ein einfacher Orc, der sich in dunkle Kräfte verfing, die er nicht begreifen konnte.\n\nFindet so viele seiner frühen Schriften, wie Ihr könnt, vielleicht bekommen wir so unsere Antworten.", sourceObjective = "Sammelt ein dunkles Pergament aus der Schattenmondgrabstätte.", progress = "Habt Ihr Ner'zhuls Aufzeichnungen gefunden?", completion = "Ihr habt meinen Dank. Ich werde es sofort zur Schwarzen Festung zurückbringen.\n\nHier, nehmt das. Ich habe es von einem Mitglied des Schattenmondklans... erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[37164] = { id = 37164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jägerinnen", description = "Ich bevorzuge es, unerkannt zu bleiben, aber ich will Euch nichts Böses. Auch warum ich hier bin, soll mein Geheimnis bleiben. Alles, was ich brauche, ist eine Unterkunft für die Nacht.\n\nWie ich sehe, seid Ihr jemand, der sich nicht so einfach einschüchtern lässt. Sehr gut, vielleicht könnt Ihr mir bei meiner Suche helfen.\n\nIch suche jemand. Wer das ist, spielt keine Rolle. Alles, was Ihr wissen müsst, ist, dass ich Euch reich entlohnen werde für jegliche Hinweise auf Hochelfenwaffen, die Ihr findet.", sourceObjective = "Sammelt einen Silberspitzenpfeil aus der Schattenmondgrabstätte.", progress = "Habt Ihr etwas gefunden?", completion = "Das ist... das ist unmöglich.\n\nIch muss weg, hier ist Eure Belohnung. Ich trenne mich nur ungern davon...", sourceObjectiveStatus = "unverified-source-field" }
quests[37165] = { id = 37165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cenarische Belange", description = "He Mann!\n\nDer Zirkel des Cenarius hat Zen'Kiki hergeschickt, um sich die Ursprünglichen anzusehen. Wär' schon früher gekommen, doch ich hatt' 'n paar Probleme damit, meine Fluggestalt anzunehmen, Mann.\n\nDie Pflanzen hier... ich kann ihre Stimmen hör'n. Die schrei'n die ganze Zeit. Wütend und aggressiv schrei'n sie herum.\n\nWürdet Ihr Zen'Kiki ein Blatt von diesem Immergrünen Flor beschaffen, von dem alle red'n? Vielleicht kann ich rausfinden, was die wollen.", sourceObjective = "Holt einen seltsam leuchtenden Wedel aus dem Immergrünen Flor.", progress = "Na, wart Ihr erfolgreich, Mann?", completion = "Das... ist nich' gut. Sie woll'n den ganzen Planeten verschlingen. Wie sind die nur so wütend geword'n? Was ist mit denen passiert? Ich werd' das dem Zirkel melden. Wir werden sicher bald wieder Eure Hilfe benötig'n.\n\nEiner von den Wedeln hier ist ein bisschen magisch, behaltet ihn eine Weile.", sourceObjectiveStatus = "unverified-source-field" }
quests[37166] = { id = 37166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titanenevolution", description = "Ah, hallo! Ihr müsst wirklich nicht so überrascht tun! Habe ich nicht auch die Gefahren der Mogu'shangewölbe überwunden? Ich bin zäher, als ich aussehe!\n\nUnd ich habe schon viel über die Geschichte dieses wundervollen Orts gelernt. Wusstet Ihr, dass die Titanen, die unsere Welt besuchten, auch hier waren?\n\nZumindest bin ich davon überzeugt! Es gibt sicher noch immer Zeichen für die Anwesenheit der Titanen. Wenn Ihr eines entdeckt, würde ich es nur zu gerne sehen!", sourceObjective = "Besorgt ein überwuchertes Artefakt aus dem Immergrünen Flor.", progress = "Habt Ihr hier Spuren der Titanen gefunden?", completion = "Das ist genau das, worauf ich gehofft habe! Ich werde es sofort untersuchen.\n\nWährend Ihr fort wart, habe ich diese hübschen Blumen für Euch gepflückt!", sourceObjectiveStatus = "unverified-source-field" }
quests[37167] = { id = 37167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aber ja keine Streitkolben!", description = "Es werden einfach zu viele blauäugige junge Schurken durch dieses Portal in den Krieg geschickt. Wenn ich meine Akademie wiedereröffnen will, müssen wenigstens ein paar von ihnen die Reise überstehen.\n\nWenn ich schon hier bin, dachte ich mir, kann ich ja auch die Chance nutzen und Vorräte für meine große Neueröffnung sammeln. Ohne reichlich Dolche kommt man da schließlich nicht weit.\n\nSchnappt mir eine Kiste mit Waffen vom Grimmgleisdepot. Dort sollten genug rumstehen. Ich hab auch was Nettes für Euch.", sourceObjective = "Beschafft eine riesige Waffenkiste im Grimmgleisdepot.", progress = "Habt Ihr ein paar Waffen für mich gefunden?", completion = "Ja, die werden ihren Zweck erfüllen. Ich danke Euch, und hier... nehmt Eure Belohnung.\n\nVersucht, nicht zu sterben, vielleicht brauche ich Euch noch einmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[37168] = { id = 37168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leorajh der Erleuchtete", sourceObjective = "<Dieser seltsam sanftmütige Saberon legt sich seine riesige Pranke auf seine Brust.>\n\nIch Leorajh. Nicht wie die anderen. War klein... schwach. Wurde vom Klan verbannt. Keine Blutmähne mehr...\n\nLeorajh findet Höhle. Findet Stein des Sonnenlichtes. Lernt viel von Stein. Will mehr lernen. Will neuen Klan.\n\nIhr stark. Habt Klan?\n\nLeorajh mitkommen?", sourceObjectiveStatus = "unverified-source-field" }
quests[37177] = { id = 37177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Klauenkönigs", sourceObjective = "Sprecht mit Terokks Geist im Terokkversteck.", completion = "Ich danke Euch für Euer Kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37179] = { id = 37179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Herz für Kinder!", description = "Halt, wartet! Greift mich nicht an! Ich habe mich geändert!\n\nIm Ernst, ich habe ein neues Kapitel aufgeschlagen, versprochen. Ich habe schon monatelang nicht mehr \"UNTERGAAAAAANG!\" gesagt. Mich interessiert nur noch eins: die armen kleinen Waisen von Azeroth zu retten, die ihre Eltern in diesem tragischen Krieg verloren haben.\n\nDeshalb bin ich hier! Mit einem einzigen eisernen Miniaturstern könnte ich alle Waisen von Azeroth mit sauberem Wasser und Strom versorgen! Und niemand könnte mich dabei aufhalten!\n\nWas haltet Ihr davon, Zuckerschnäuzchen? Werdet Ihr dem alten Millhaus bei der Rettung der Waisen helfen?", sourceObjective = "Holt einen eisernen Miniaturstern von der Oberen Schwarzfelsspitze.", progress = "Habt Ihr den Eisernen Stern gefunden?", completion = "Also, Ihr seid wirklich ziemlich nützlich und furchtbar stark. Warum folge ich Euch nicht einfach eine Weile?\n\nAchtung Draenor, der UUUNTERGAAAAANG naht!", sourceObjectiveStatus = "unverified-source-field" }
quests[37180] = { id = 37180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Oger ohne sein Schwert...", description = "Bevor man mich nach Gorgrond brachte, war ich an der Zerschlagenen Anhöhe in Nagrand stationiert, um dort die Ordnung zu wahren. Wesir Dar'gud ließ mich mein Lieblingsschwert nicht mitnehmen. Er sagte, ich würde es dort, wo ich hinginge, nicht brauchen.\n\nIch will es zurück, Kommandant, und gemeinsam sind wir stark genug, um es Dar'guds blutiger Leiche zu entwenden.\n\nDas würde mir sehr viel bedeuten. Ein Oger ohne sein Schwert ist kein Oger.", sourceObjective = "Holt Tormmoks Lieblingsschwert von Wesir Dar'gud auf der Zerschlagenen Anhöhe in Nagrand.", progress = "Ich will mein Schwert mehr als ich Euch sagen kann, Kommandant.", completion = "Ja... das ist es.\n\nKommandant, jetzt, wo ich mein Schwert zurückhabe, werde ich Eure Feinde zerstückeln wie nie zuvor.", sourceObjectiveStatus = "unverified-source-field" }
quests[37181] = { id = 37181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leorajhs Gebetsperlen", description = "Als Leorajh Schamane wurde, gab der Rudelführer ihm Gebetsperlen. Gebetsperlen helfen Leorajh, die Elemente zu hören.\n\nEines Tages griffen Vogelmänner an und stahlen Gebetsperlen. Sie haben sie nach Skettis gebracht.\n\nKönnt Ihr Leorajh helfen, die Gebetsperlen zurückzubekommen?", sourceObjective = "Nehmt Leorajhs Gebetsperlen Kirox dem Windtänzer in Skettis ab.", progress = "Die Elemente sprechen nicht mehr so zu Leorajh wie früher.", completion = "Ich danke Euch! Jetzt sprechen die Elemente wieder zu Leorajh.", sourceObjectiveStatus = "unverified-source-field" }
quests[37182] = { id = 37182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahrsagen oder versagen", description = "Es gibt noch andere, die sich die Schatten zunutze machen. Ihr kennt sie, Kommandant... die Schattenmondorcs.\n\nSie sind kurz davor, ihre Fertigkeit zu vervollkommnen... Sie rufen die Schatten jenseits dieser Gefilde an...\n\nMich dürstet nach ihrer Macht. Sie haben einen unter sich, der einen besonders interessanten Stab besitzt... Wir sollten ihn für uns beanspruchen.", sourceObjective = "Holt Urnas Tiefenstab von Urna Dunkelgrund aus der Schattenmondenklave im Schattenmondtal.", progress = "Die Feinde auslöschen und gleichzeitig große Macht erlangen... Mein Volk hat dafür ein Sprichwort: Zwei Orcs mit einer Klappe schlagen.", completion = "Ja... ja... das wird reichen. Wir können das verwenden, um große Dinge zu tun.\n\nIch danke Euch, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[37183] = { id = 37183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der entscheidende Weg", description = "Die herbstlichen Wälder Taladors befinden sich an einem Scheideweg, der für diesen Kontinent unglaublich wichtig ist, Kommandant. Vor der Westküste ist die Flotte der Eisernen Horde bereits auf dem Weg von Gorgrond nach Shattrath.\n\nTalador wird fallen, wenn wir sie nicht verstärken. Ich habe mir die Freiheit herausgenommen, Vorarbeiter Eksos loszuschicken. Er hat bereits begonnen, in der Nähe der Landungsstelle der Eisernen Horde einen Außenposten für unsere Streitkräfte zu errichten. Er erwartet weitere Befehle.", sourceObjective = "Sprecht mit Dungar Trinkfest, um Euren Flug nach Talador anzutreten.", completion = "Ich werde Eure Zeit nicht verschwenden, Kommandant. Reden wir über unsere Strategie.", sourceObjectiveStatus = "unverified-source-field" }
quests[37184] = { id = 37184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht nach Nagrand tragen", description = "Gut, Euch zu sehen, Kommandant. Nach dem Verlust der Rangaristation in Telaar hat uns Verteidigerin Yrel angewiesen, einen neuen Außenposten in Nagrand zu errichten.\n\nIch habe mir die Freiheit genommen, dafür einige meiner Männer und Vorräte zur Verfügung zu stellen. Rangari D'kaan hat uns bereits benachrichtigt, dass der Außenposten bald fertiggestellt wird. Er lässt Euch mitteilen, dass alles für Euch bereit steht.\n\nEs wartet ein Greif auf Euch, mit dem Ihr die aktuelle Karawanenlieferung einholen könnt, Kommandant.", sourceObjective = "Sprecht mit Leutnant Balfor bei der Karawane in Nagrand.", completion = "Sie kamen... aus dem... Nichts.\n\n<Der Leutnant wird fast ohnmächtig.>", sourceObjectiveStatus = "unverified-source-field" }
quests[37185] = { id = 37185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Personal Summons" }
quests[37186] = { id = 37186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Art of War" }
quests[37187] = { id = 37187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Portal" }
quests[37188] = { id = 37188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Flash of Bronze..." }
quests[37189] = { id = 37189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Personal Summons" }
quests[37190] = { id = 37190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iron Horde Invasion" }
quests[37191] = { id = 37191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanketsu, die brennende Klinge", description = "Die Klinge ist glühend heiß. Das Juwel auf dem Schwertgriff strahlt Euch an, als wolle es Euch auffordern, das Schwert zu ergreifen.\n\nVielleicht gibt es in Eurer Garnison jemanden, der sich diese Waffe gerne ansehen würde.", sourceObjective = "Bringt Sanketsu, die brennende Klinge, zu Leutnant Dorn in Eurer Garnison.", completion = "<Leutnant Dorn untersucht die Waffe und betrachtet dabei jedes Detail, jede Kante und jeden Kratzer. Nach kurzer Zeit beginnt sie zu sprechen.>\n\nBeeindruckende Arbeit.\n\nDiese Klinge wurde von einem Meister seines Fachs geschliffen und mit uralter Magie erfüllt.\n\nStellt Euch vor, was für eine mächtige Waffe sie in den Händen eines erfahrenen Kriegers wäre...", sourceObjectiveStatus = "unverified-source-field" }
quests[37192] = { id = 37192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanketsu, die brennende Klinge", description = "Die Klinge ist glühend heiß. Das Juwel auf dem Schwertgriff strahlt Euch an, als wolle es Euch auffordern, das Schwert zu ergreifen.\n\nVielleicht gibt es in Eurer Garnison jemanden, der sich diese Waffe gerne ansehen würde.", sourceObjective = "Bringt Sanketsu, die brennende Klinge, zu Kriegsmeister Zog in Eurer Garnison.", completion = "<Kriegsmeister Zog hält das Schwert hoch in die Luft und begutachtet seine Balance und sein Gewicht.>\n\nEine solche Waffe habe ich noch nie gesehen. Es ist klar, dass sie das Werk eines wahren Meisters ist. Uralte Magie schlummert in ihr und sie hat sich in vielen Schlachten bewährt.\n\nKommandant, ich überlasse die Entscheidung Euch, aber es wäre eine Ehre, dieses Schwert im Dienste der Garnison zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[37193] = { id = 37193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The King's Command" }
