quests[37198] = { id = 37198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Visitor: Sappy" }
quests[37199] = { id = 37199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Visitor: Sappy" }
quests[37201] = { id = 37201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cymre Leuchtklinge", description = "Bei einer kürzlichen Ausgrabung habe ich einige interessante Artefakte entdeckt und würde sie sehr gerne auf die Probe stellen, um zu sehen, was sie ihren ursprünglichen Kulturen gebracht hätten. Habt Ihr zufällig etwas Kleines und Flauschiges, das sich nicht vor einem Kampf scheut?", sourceObjective = "Bezwingt Cymre Leuchtklinge im Haustierkampf.", completion = "Ich danke Euch für die Hilfe beim Testen der Artefakte.", sourceObjectiveStatus = "unverified-source-field" }
quests[37202] = { id = 37202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hemet Nesingwary Visitor Tracking Event" }
quests[37203] = { id = 37203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashlei", description = "Ich mag es eigentlich nicht, wenn meine Haustiere kämpfen, aber ich nehme sie danach so gern in den Arm, damit es ihnen besser geht.", sourceObjective = "Besiegt Ashlei im Haustierkampf.", progress = "Hallo.", completion = "Das hat Spaß gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[37204] = { id = 37204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine alte Flamme neu entfachen", description = "Ich werde sterben, {race}. Mein Feuer qualmt nur noch... bald wird mein Licht flackern und verlöschen.\n\nDas dürft Ihr nicht zulassen. Bringt mir eine Essenz der Flamme. Schenkt meiner Existenz einen weiteren Tag, dann werde ich jeden Brecher verbrennen, das schwöre ich.\n\nIch werde meine Geschwister rächen.", sourceObjective = "Bringt die Essenz der Flamme zu Firaga in Magnarok.", completion = "Die Flammen, sie brennen in mir!", sourceObjectiveStatus = "unverified-source-field" }
quests[37205] = { id = 37205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gargra", description = "Wollt Ihr sie herausfordern? Meine Wölfe brauchen Training, um stark zu werden.", sourceObjective = "Besiegt Gargra im Haustierkampf.", completion = "Ihr habt beim Training meiner Welpen geholfen, dafür bin ich dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[37206] = { id = 37206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tarr der Schreckliche", description = "Tarr ist der wahre Kriegsfürst! Führt Eure Armee in den Kampf, dann werdet Ihr es erleben.", sourceObjective = "Besiegt Tarr den Schrecklichen im Haustierkampf.", progress = "Tarr zerschmettert Euer Gesicht!", completion = "Dieses Mal hattet Ihr Glück.", sourceObjectiveStatus = "unverified-source-field" }
quests[37207] = { id = 37207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vesharr", description = "Ich hatte eine Vision, dass jemand kommen würde, der Haustiere gemeistert hat, um mich herauszufordern. Wird diese Vision nun endlich Wirklichkeit?", sourceObjective = "Besiegt Vesharr im Haustierkampf.", progress = "Könnt Ihr mich besiegen?", completion = "Die Federn sind gefallen und haben uns viel gezeigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[37208] = { id = 37208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taralune", description = "Ich bemühe mich, meine Lehren durch nicht tödliche Haustierkämpfe zu vermitteln. Seid Ihr gewillt, zu lernen?", sourceObjective = "Besiegt Taralune im Haustierkampf.", completion = "Wir haben voneinander gelernt. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[37209] = { id = 37209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalter Stahl, Teil II", description = "He, Ihr da.\n\nIch wollte mich bei Euch für das bedanken, was Ihr für mich getan habt. Das Gefühl dieser Kanone in meinen Händen ist die einzige Therapie, die ich brauche. Aber jetzt...\n\n<Keeshan starrt in die Ferne und verzieht das Gesicht.> ...sind die Kugeln ausgegangen.\n\nDann werde ich wohl einfach hier sitzenbleiben und auf den Tod warten.", sourceObjective = "Findet eine Eiserne Autokanone im Grimmgleisdepot.", progress = "Lasst mich in Ruhe.", completion = "Ah, genau richtig. Mir wird zwar bald die Munition ausgehen, aber wenigstens habe ich eine Weile lang einen Grund zu leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[37210] = { id = 37210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aogexons Reißzahn", progress = "Aogexon ist eine der am stärksten gefürchteten Bestien in Nagrand und einer der größten und gefährlichsten Waldpirscher, die ich je erblickt habe!\n\nEs haben sich schon mehrere Sammler an mich gewandt und ihr Interesse an Aogexons tödlichen Reißzähnen geäußert. Wenn Ihr nicht vor der Herausforderung zurückschreckt, könnt Ihr Aogexon gelegentlich im nahe liegenden Sumpf entdecken.\n\nViel Glück!", completion = "Gute Arbeit, {name}! Ihr habt den Sumpf zu einem sichereren Ort für die Archäologie gemacht und uns gleichzeitig einen Profit eingebracht!" }
quests[37211] = { id = 37211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergruus Horn", progress = "Ein anonymer Sammler von wertvollen Fossilien und Antiquitäten hat der Werterhaltungsgesellschaft eine riesige Belohnung für Bergruus Horn versprochen.\n\nEine riesige Belohnung, {name}... RIESIG!", completion = "Wow! Ich wusste ja, dass Begruus Horn groß sein würde, aber ich hätte nie erwartet, dass es dermaßen riesig ist!\n\nDa müssen wir dem Käufer wohl einen Transportaufschlag berechnen!" }
quests[37212] = { id = 37212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Proving Grounds - Damage Bronze" }
