quests[37220] = { id = 37220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Proving Grounds - Healer Gold" }
quests[37221] = { id = 37221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dekorhans Stoßzahn", progress = "Nur wenige Elekks leben so lange wie Dekorhan. Die Hauer von Elekks wachsen ihr ganzes Leben lang.\n\nDaher gehören Dekorhans Hauer zu den größten und ältesten in Draenor.\n\nHört Ihr das auch, {name}? Das ist das Klimpern von Gold in unseren Taschen, nachdem Ihr Dekorhans Hauer beschafft habt!", completion = "Was für ein Fund! Gute Arbeit! {name}!\n\nDekorhans Hauer wird das Herzstück irgendeiner Sammlung werden." }
quests[37222] = { id = 37222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terrorhufs Balg", progress = "Bei den meisten Talbuks handelt es sich um friedliche Wesen, die nur angreifen, wenn sie ihre Herde verteidigen. Terrorhuf ist anders. Dieser Talbuk ist eines der aggressivsten und gefährlichsten Wildtiere, das ich je gesehen habe... und einer der prächtigsten Talbuks weit und breit!\n\nWenn Ihr auf Euren Abenteuern auf Terrorhuf stoßt und lebendig davonkommt, bringt mir den Balg des Tieres, dann werde ich Euch gut belohnen!", completion = "Ich werde Euch nicht anlügen, {name}... Ich werde jetzt besser schlafen, da ich weiß, dass sich Terrorhuf nicht mehr in der Wildnis dort draußen herumtreibt.\n\nUnd natürlich werde ich auch besser schlafen, wenn ich meine Matratze mit all dem Geld ausstopfe, das mir ein reicher Sammler dafür zahlen wird!\n\nKa-tsching!" }
quests[37223] = { id = 37223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gagrogs Schädel", progress = "Tief im Walde des nördlichen Nagrands befindet sich ein riesiger Gronn, der als Gagrog der Metzler bekannt ist. Und nein, den Namen hat er sich nicht verdient, weil er bei Umarmungen immer so sanft zudrückt... dieser Gronn ist so wild und mordlustig, wie es nur geht!\n\nUnd dass es klar ist, ich will Euch jetzt nicht sagen, dass Ihr versuchen solltet, das Ding zu jagen... das wäre Selbstmord... aber falls Ihr aus Versehen auf ihn stoßen solltet und bei lebendigem Leibe davonkommt, bringt mir auf jeden Fall seinen Schädel!", completion = "Ich kann meinen Augen nicht trauen... Ihr habt allen Ernstes Gagrog den Metzler bezwungen? Ihr seid zäher, als ich angenommen hatte!\n\nAusgezeichnete Arbeit, {name}!" }
quests[37224] = { id = 37224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mu'gras Kopf", progress = "Unweit von hier befindet sich ein Nilpferd von ungewöhnlicher Größe und Wildheit, das Mu'gra genannt wird. Ein privater Sammler hat sich an mich gewandt, da er Mu'gras Zähne für eine spezielle Ausstellung ergattern möchte.\n\nNilpferdzähne zu ziehen ist äußerst schwierig, und wir können ja keine kaputten Waren verkaufen, also bringt mir einfach den ganzen Kopf, verstanden?\n\nNa dann, viel Glück!", completion = "Hui! Sieh sich einer an, wie groß dieses Ding ist... das ist der größte Nilpferdkopf, der mir je untergekommen ist!\n\nMu'gra war eines der wütendsten Nilpferde, das ich je gesehen habe, aber jetzt lächelt es!\n\nVerstanden? Nilpferdzähne... Lächeln... nicht?" }
quests[37225] = { id = 37225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thek'talons Kralle", progress = "Windrocs findet man in ganz Nagrand verteilt, von den höchsten Gipfeln zu den niedrigsten Tälern. Ein Windroc ist jedoch besonders schwer zu fassen und wird nur selten gesehen. Die Orcs nennen ihn Thek'talon.\n\nWenn ich mich mit einer Sache auskenne, dann mit dem enormen Wert von so seltener und schwer zu beschaffender Ware!", completion = "Was habt Ihr denn da?\n\n<Gazmolf betrachtet die Kralle.>\n\nHey! Das sieht zweifelsohne nach Thek'talon aus, und selbst, wenn ich mich da irre, wer will mir schon widersprechen? Gute Arbeit, hier habt Ihr Euren Anteil!" }
quests[37226] = { id = 37226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xelganaks Stachel", progress = "Tödlicher als Xelganak kann man kaum sein, {name}! Wenn man Xelganak jagen will, muss man schon nach Geld, Abenteuer und Ruhm süchtig sein.\n\nXelganaks Giftstachel würde sich beim passenden Sammler großer Beliebtheit erfreuen, also falls Ihr keine Herausforderung scheut, könnte ich Euch eine große Belohnung dafür sichern.\n\nPasst nur auf, dass er nicht Euer Gesicht schmilzt, wie beim armen Bozzil.", completion = "Hey! Seid ein wenig vorsichtiger mit dem Stachel!\n\n<Gazmolf untersucht Xelganaks Stachel.>\n\nAußergewöhnlich... so etwas habe ich noch nie zuvor gesehen. Als erstklassiger Archäologe ist es mir eine Ehre, diesen Gegenstand künstlich zu fossilisieren und an den Höchstbietenden zu verkaufen.\n\nGut gemacht!" }
quests[37227] = { id = 37227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Vogel haben", description = "{name}! Habt Ihr das Pfauenküken gesehen, das Ihr letztens gerettet habt?\n\n<Mylune hält ein Pfauenküken hoch und trillert und zwitschert in seine Richtung. Sie zeigt auf Euch, sagt Euren Namen und tschilpt anschließend den kleinen Vogel angeregt weiter an. Die beiden ignorieren Euch und führen eine lange Unterhaltung in der Vogelsprache – so lange, dass Ihr anfangt, Euch unbehaglich zu fühlen. Schließlich wendet die Dryade ihre Aufmerksamkeit wieder Euch zu.>\n\nHabt Ihr das gehört? Im Immergrünen Flor sind noch mehr Pfauenküken gefangen! Wenn Ihr sie nicht rettet... aber Ihr habt ja selbst gehört, was dann passiert!", sourceObjective = "Sucht ein winziges Pfauenküken im Immergrünen Flor.", progress = "<Mylune stampft ungeduldig mit ihren Hufen.>", completion = "Ach, vielen Dank, {name}! Ihr habt vielen kleinen Vogelbabys eine große Freude bereitet.\n\n\n\n\n\nIhr seid mein liebster {race}!", sourceObjectiveStatus = "unverified-source-field" }
quests[37228] = { id = 37228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein fruchtbarer Vorschlag", description = "Der Kopf eines EINZELNEN Ogers wird die Obstverkäuferin nicht aufhalten. Nein, mit der Obstverkäuferin ist nicht gut Kirschen essen, die hat was in der Birne.\n\nBringt mir NOCH EINEN Ogerkopf! Ha! Was wird die Obstverkäuferin dann tun? In ihre Bananen heulen, bis sie verfaulen und auf den Boden fallen.\n\nERZITTERT, OBSTVERKÄUFERIN! KÖSTLICH!", sourceObjective = "Besorgt einen riesigen Ogerkopf aus der Blutschlägermine.", progress = "DIE OBSTVERKÄUFERIN HAT KEINE CHANCE!", completion = "Wir sind einen Schritt näher daran, die Trauben der Obstverkäuferin zu trübem Wein zu stampfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37229] = { id = 37229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie ein Zwerg in einem Bergwerk", description = "Baelog und Eric schwör'n Stein und Bein, dass sich ganz unten in der Mine ein Schatz befindet. Warum? Weil's eine Mine ist! Und wir lieben funkelnde Steine.\n\nLetztes Mal wurden wir von riesigen Ogern zurückgeschlag'n. Baelog hat uns mit seinem Schwert den Rücken freigehalten, während Eric vorausgestürmt ist, um einen schnellen Ausgang zu find'n.\n\nUnd wisst Ihr was? Ich hab schon WIEDER meinen Schild verloren!\n\n<Olaf sieht Euch flehend an.>", sourceObjective = "Beschafft Olafs Schild aus der Blutschlägermine.", progress = "<Olaf schluchzt.>", completion = "Beim Licht, das ist er! Ihr habt es schon wieder geschafft, und ich kann Euch nicht genug danken! Nächstes Mal werd'n wir versuch'n, vorsichtiger zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[37230] = { id = 37230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutgeld", description = "Willkommen zurück, Kommandant. Der Kommandant ist offenbar in großer Eile, und die Überlegung, <seine/ihre> Stiefel oder den Mantel abzulegen, um nicht den gesamten Boden vollzutropfen, wäre zu viel der Rücksichtnahme.\n\nErinnert sich der Kommandant an die säurehaltige Lösung? Sie war ziemlich wirksam, obwohl ein Fass nicht ausgereicht hat, um ALLE Blutflecken von den Gemälden, Wandteppichen und der Decke zu entfernen.\n\nDas war bestimmt der heldenhafteste und klebrigste Kampf in der jüngeren Geschichte.", sourceObjective = "Besorgt ein Fass schrecklich säurehaltiger Lösung von den Eisendocks.", progress = "War der Kommandant erfolgreich?", completion = "Es dürften zwar noch mehr dieser Fässer existieren, aber unter diesen Umständen muss dieses eine Fass genügen, da ich ja davon ausgehen muss, dass Ihr Euch als Kommandant um wichtigere Belange kümmern müsst, die das ganze Land betreffen, und keine Zeit habt, den Dreck aufzuräumen, den Eure Euch treu folgenden Gefährten so flächendeckend in der ganzen Gegend verteilt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[37231] = { id = 37231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche geht weiter", description = "Ein alter Deckmatrose hat das Gerät untersucht, das Ihr uns gebracht habt, und glaubt, dass es sich dabei um eine gekonnte Fälschung handelt. Diese Eiserne Horde versucht, den Mechanismus zu kopieren, doch fehlt ihr die Technologie dafür.\n\nGenau gesagt wissen wir nicht, wie diese primitiven Bestien an ein solches Werkzeug gelangen konnten. Wenn wir es wüssten, würde es kein so gutes Seemannsgarn abgeben, ha!\n\nWir haben immer noch einen Schatzhaufen, der Euren Namen trägt, wenn Ihr den echten Kompass für uns findet.", sourceObjective = "Findet den Messingkompass an den Eisendocks.", progress = "Habt Ihr den Kompass gefunden?", completion = "Hoffentlich ist der jetzt echt. Jedes Mal, wenn ich durch das Portal gehe, steht mir das Fell zu Berge.", sourceObjectiveStatus = "unverified-source-field" }
quests[37232] = { id = 37232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelenschnitzerin Voss", description = "Ihr da! Ihr habt also die Klinge für mich gefunden? Ich brauche erneut Eure Hilfe.\n\nDie Klinge hat wunderbar funktioniert und mir dabei geholfen, die gequälten Untoten aus dieser Welt zu schneiden. Ihre Schreie waren Musik in meinen Ohren.\n\nDie Seelenschnittklinge kann jedoch nicht repariert werden, da sie zum Teil mit Geistenergie verwoben ist, aus der sie jedes Mal, wenn eine Seele befreit wird, schöpft. Ich brauche noch eine Klinge, hier sind nämlich nach wie vor finstere Mächte am Werk, die Geister erwecken und sie umwandeln.", sourceObjective = "Beschafft eine Seelenschnittklinge aus Auchindoun.", progress = "Habt Ihr die Klinge gefunden?", completion = "Oh ja, die hier ist perfekt. Kleine Seelen, es wird Zeit, in die verschlungene Finsternis zurückzukehren.\n\n<Lilian lacht irre gackernd.>", sourceObjectiveStatus = "unverified-source-field" }
quests[37233] = { id = 37233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefäß der Tugend", description = "Ach, da seid Ihr ja wieder, Kommandant. Diese Seuche beschäftigt mich noch immer, doch vom Licht geleitet werde ich entschlossen handeln.\n\nDas Seelenflechtgefäß war bei unseren Untersuchungen der jenseitigen Welt und des Übergangs vom Leben zum Tod hilfreich. Wenn wir mehr Gefäße hätten, könnten wir vielleicht die Wahrheit hinter der Brücke zwischen den Welten herausfinden. Vielleicht gibt es einen Grund dafür, dass die Verseuchten diesen Übergang nicht komplett vollziehen.\n\nDie Argentumdämmerung weiß jegliche weitere Hilfe sehr zu schätzen.", sourceObjective = "Besorgt ein Seelenflechtgefäß in Auchindoun.", progress = "Habt Ihr etwas gefunden?", completion = "Auch wenn ich bald wieder zur Kapelle des Hoffnungsvollen Lichts zurückkehren muss: Habt erneut meinen ergebensten Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[37234] = { id = 37234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die innere Finsternis", description = "Das Licht... ist verloschen. Ich weiß nicht, warum.\n\nIch mache mir jetzt mehr Sorgen als vorher und finde kaum Trost im Alltag. Jeder neue Tag erscheint mir dunkler als der letzte.\n\nBringt mir bitte noch einen Sonnenkristall. Sein Licht ist so warm und tröstlich.", sourceObjective = "Beschafft einen Sonnenkristall in Himmelsnadel.", progress = "Habt Ihr den Kristall gefunden?", completion = "Die Wärme tröstet mich. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[37235] = { id = 37235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bitte an den Himmel", description = "Bisher waren unsere Versuche, die Arakkoa zu kontaktieren, erfolglos. Jeder neue Versuch verschleißt das Gefieder und hinterlässt eine ramponierte, kaputte Feder.\n\nAviana fleht Euch an, eine andere Feder für sie zu finden, Kommandant. Wir wollen nicht mit ansehen, wie unsere Brüder Opfer ihres eigenen gewalttätigen Naturells werden. Alle Lebewesen des Himmels, sei es zu Lebzeiten oder danach, sind uns willkommen.", sourceObjective = "Sammelt makelloses Gefieder in Himmelsnadel.", progress = "Habt Ihr die Feder mitgebracht?", completion = "Wir werden weiter mit den Arakkoa verhandeln.\n\nMöge Aviana Euch segnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37236] = { id = 37236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie der Vater so der Sohn", description = "Er hat es schon wieder getan! Mein Sohn hat mein Messer genommen und etwas über eine \"chromatische Haut\" gerufen, bevor er zur Spitze davongerannt ist! Was er mit so etwas wohl anfangen würde? Sie wie einen Umhang tragen?\n\nWürdet Ihr wohl die Augen nach dem Messer offenhalten, wenn es keine allzu großen Umstände macht? Ihr wisst schon, wenn Ihr wieder einmal in der Gegend der Oberen Schwarzfelsspitze seid. Was hoffentlich bald der Fall sein wird. SEHR bald.", sourceObjective = "Findet Pips verbesserten Kürschner an der Schwarzfelsspitze.", progress = "Wo ist mein Messer?", completion = "Ihr habt es gerettet! Es ist ein bisschen schartig, doch das kann ausgebessert werden. Vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[37237] = { id = 37237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche eines Helden endet nie", description = "Zum Gruße, <Knappe/Schildmaid> {name}! Seit unserer letzten Unterhaltung habe ich mich heldenhaft den Toren der Schwarzfelsspitze genähert und zwar mit der noblen Absicht, die zähnefletschende Herrschaft ihrer Drachen zu beenden.\n\nDoch als ich mich dem Ort näherte, überkam mich die Erinnerung an das hübsche Gesicht meiner Doloria und an meine eigenen schmerzhaften, unbefriedigten Bedürfnisse.\n\nMein Schwertarm sackte schlaff an meine Seite.\n\nNun fordere ich EUCH auf, <mein Knappe/meine Schildmaid>, an meiner Stelle loszuziehen und die Obere Schwarzfelsspitze abzusuchen. Ich muss wissen, ob sich die Drachen noch durch ihre Gänge winden.", sourceObjective = "Sammelt eine abgestoßene Protodrachenklaue.", progress = "Habt Ihr Beweise für Drachen gefunden?", completion = "Beim Licht, sie vermehren sich wie große, Feuer spuckende Karnickel! Ich werde mich gleich dorthin begeben und mindestens DREISSIG von den großen Bestien besiegen.\n\nFür Doloria!", sourceObjectiveStatus = "unverified-source-field" }
quests[37238] = { id = 37238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse des Seelenbindens", description = "Wir haben Ner'zhul's Aufzeichnungen durchgesehen, die Ihr uns vor Kurzem gebracht habt. Obwohl wir kurz davor sind, zu verstehen, wie diese Hexenmeister gelernt haben, Seelen zu binden und die Untoten zu beherrschen, fehlen uns noch wichtige Puzzleteile.\n\nUm das Geheimnis vollständig ergründen zu können, benötigen wir mehr Seiten. Ich möchte nicht mit bruchstückhaften Informationen herumexperimentieren und am Ende eine Entartung erschaffen. Davon gibt es bereits genug in Nordend.", sourceObjective = "Holt ein dunkles Pergament aus der Schattenmondgrabstätte.", progress = "Habt Ihr Ner'zhuls Aufzeichnungen gefunden?", completion = "Wir sind für Eure Hilfe dankbar. Ich werde mich gleich zurückziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37239] = { id = 37239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksal des Gefallenen", description = "Ich fühle, dass ich Euch vielleicht trauen könnte. Immerhin habt Ihr mit niemandem über mein Geheimnis gesprochen, dafür danke ich Euch.\n\nIch benötige erneut Eure Hilfe und bin im Gegenzug bereit, eigene Informationen, die ich habe, mit Euch zu teilen. Ich bin hier, weil ich eine Elfe namens Alleria suche. Sie verschwand vor einigen Jahren in Draenor. Ich habe die vage Hoffnung, dass der Wirbelnde Nether sie hierher gebracht hat.\n\nIch weiß, es klingt unwahrscheinlich, aber haltet nach Hochelfen oder Zeichen von ihnen Ausschau, wenn Ihr unterwegs seid.", sourceObjective = "Holt einen Silberspitzenpfeil aus der Schattenmondgrabstätte.", progress = "Habt Ihr etwas gefunden?", completion = "Noch einer? Merkwürdig.\n\nIch bin vielleicht nicht näher daran, sie zu finden, aber immerhin trösten mich diese Pfeile.", sourceObjectiveStatus = "unverified-source-field" }
quests[37240] = { id = 37240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Blattleser", description = "Schön, Euch wiederzuseh'n!\n\nDer Zirkel des Cenarius hat Zen'kiki hier rausgeschickt, um mehr von den Pflanz'n zu such'n. Was wir hier seh'n, gefällt uns gar nich'.\n\nWenn Ihr mehr von diesen Blättern findet, bringt eins zurück. Sie durchschau'n Zen'kikis Baumverkleidung sogar, wenn er sich in den Bod'n pflanzt!\n\nUnd das macht das Lauf'n schwieriger!", sourceObjective = "Holt einen seltsam leuchtenden Wedel aus dem Immergrünen Flor.", progress = "Na, wart Ihr erfolgreich, Mann?", completion = "Danke, Mann. Ich bring's zum Zirkel zurück, sobald ich rausfinde, wie man in den stürmischen Winden hier in der Gegend fliegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[37241] = { id = 37241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lektionen der Vergangenheit", description = "Ich bin wieder da! Ihr wusstet doch bestimmt, dass ich mich nicht lange von einer Welt so reich an Geschichte fernhalten können würde!\n\n<Lehrensucher Cho gluckst und hält sich den riesigen Bauch.>\n\nVielleicht habe ich seit der Säuberung des Tals an zu vielen Festmahlen teilgenommen. Es gibt so viel zu feiern in Pandaria!\n\nFalls Ihr in Zukunft Hinweise auf titanischen Einfluss auf die einheimischen Arten findet... Ich werde hier sein und mich von Herzen am Grollhufbraten erfreuen.", sourceObjective = "Besorgt ein überwuchertes Artefakt aus dem Immergrünen Flor.", progress = "Habt Ihr hier Anzeichen auf die Titanen gefunden?", completion = "Ein weiteres vorzügliches Fundstück von unserem glorreichen Helden! Ich werde unverzüglich mit der Niederschrift Eurer heroischen Taten beginnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[37242] = { id = 37242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernen tut weh", description = "Die Akademie ist fertiggestellt... an einem geheimen Ort, versteht sich. Vielleicht existiert sie ja gar nicht wirklich?\n\nApropos, mir gehen langsam die scharfen, spitzen Unterrichtshilfen aus.\n\n<Lonika zwinkert Euch mehrmals zu und verabreicht Euch dann mit ihrem Dolch einen Stoß in die Rippen.>", sourceObjective = "Beschafft eine riesige Waffenkiste im Grimmgleisdepot.", progress = "Habt Ihr ein paar Waffen für mich gefunden?", completion = "Ihr habt Euch erneut als unbezahlbar erwiesen. Hättet Ihr gern eine Stelle als Lehrer?", sourceObjectiveStatus = "unverified-source-field" }
quests[37243] = { id = 37243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit geschliffener Axt", description = "Ich, Gamon, habe viele Orcschädel gespalten. Trotzdem hat die Eiserne Horde nach wie vor viele Mitglieder mit einer Menge Gliedmaßen und Blut. Davon werde ich sie befreien!\n\nBeziehungsweise würde ich das, wenn ich eine Axt hätte. Die letzte ist mitten in einem Orcbrustkorb zerbrochen.\n\n<Gamon lacht herzhaft.>\n\nBringt mir eine neue, damit ich mir den Weg durch dieses Land spalten kann!", sourceObjective = "Findet einen Eisernen Gliedmaßenspalter im Grimmgleisdepot.", progress = "Was?", completion = "Eine gewaltige Klinge, die ich aber bald abnutzen werde. Orcköpfe sind härter als sie aussehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37244] = { id = 37244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flammenfliegenfalle", description = "Der alte Winky ist noch nich' wieder da! Ich fang an, mir Sorgen zu machen.\n\nSeid so nett und besorgt noch 'ne Flammenfliege von der Oberen Schwarzfelsspitze. Wenn wir genug davon haben, sieht Winky bestimmt das Glühen und kommt zurück.\n\nUnd dann haben wir ihn genau da, wo wir ihn haben wollen!", sourceObjective = "Fangt an der Oberen Schwarzfelsspitze eine Flammenfliege der Spitze.", progress = "Habt Ihr noch eine Fliege erwischt?", completion = "Ui, das is* vielleicht 'ne helle Fliege! Dank Euch schön, wir werd'n einfach weitermach'n, bis der alte Winky heimkommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[37245] = { id = 37245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geflüster in der Dunkelheit", description = "Stört mich nicht, ich versuche gerade alles in meiner Macht Stehende, um zu verhindern, dass unsere Welten in die Leere hinabstürzen. Als hätten wir das nicht schonmal gehabt.\n\nOh, richtig, Ihr habt mir doch das letzte Mal geholfen, nicht? Euer Timing ist exzellent. Ich brauche einen weiteren Schlüssel zum Leerentor.\n\nWas wollt Ihr denn noch hier? Die unendlichen Schrecken des Abgrunds warten nicht, bis Ihr Euren Schönheitsschlaf gehalten habt! Es scheint ihnen in ihren vielen Tentakeln zu jucken.", sourceObjective = "Findet einen Schlüssel zum Leerentor in der Schattenmondgrabstätte.", progress = "Euch ist schon klar, dass uns die Zeit, die Ihr hier mit Schwatzen verschwendet, der Verdammnis immer näher bringt?", completion = "Perfekt, hier ist eine Belohnung für Eure Mühen.\n\nIch muss mich jetzt aufmachen und alle retten. Mal wieder.", sourceObjectiveStatus = "unverified-source-field" }
