quests[37255] = { id = 37255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "COLISEUM WINNER FLAG (WEEKLY RESET)" }
quests[37256] = { id = 37256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie kamen aus dem Meer", description = "Ihr seid auf der Suche nach Prinz Farondis?\n\n<Die Augen der geisterhaften und argwöhnischen Elfe verengen sich zu Schlitzen.>\n\nIch kann Euch zu Farondis bringen... Aber der Reihe nach... Diese Naga haben urplötzlich angegriffen. Ihren Befehlshaber, einen gewissen Zarrin, findet Ihr in den flachen Hügeln im Westen.\n\nWenn Ihr mir helft, den Kopf von Zarrin zu erbeuten, werde ich Euch anhören.", sourceObjective = "Holt Euch den Kopf von Tiefenkommandant Zarrin und tötet 8 seiner Nagakämpfer.", progress = "<Der Nachtwächter schaut Euch erwartungsvoll an.>", completion = "<Idri schaut sich den hässlichen Kopf an.>\n\nJa, das ist er.", sourceObjectiveStatus = "unverified-source-field" }
quests[37257] = { id = 37257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bis auf die Knochen", description = "Ihr sucht Golganneths Gezeitenstein?\n\nJa, ich weiß, wo er ist. Er ist an einem Ort, an den ich nicht mehr zurückkehren möchte.\n\nIhr könntet mir vielleicht von Nutzen sein. Im Zuge dieses Nagaangriffs sind diese widerwärtigen Fischleute über mein Land gekrochen und haben unsere Grabstätten geschändet. Sie haben die Gebeine unserer Vorfahren und meiner Familie gestohlen.\n\nHelft mir, meinen Leuten etwas Trost zu spenden. Dann werde ich Euch etwas mehr über den Gezeitenstein erzählen.", sourceObjective = "Sammelt 55 gestohlene Nachtelfenknochen ein.", progress = "Ich bin meinen Leuten wohl eher egal, aber trotzdem sind sie mir nicht egal.", completion = "Unsere Knochen sind die letzte Erinnerung an ein Leben, das wir lange hinter uns gelassen haben.\n\n<Der Prinz sieht Euch eindringlich in die Augen.>\n\nBleibt bei mir, {class}. Ich werde Euch helfen, den Gezeitenstein zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[37259] = { id = 37259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Teron'gor", description = "{name}, Ihr müsst eine furchtlose Gruppe zusammenstellen und sie in die Tiefen von Auchindoun führen. Aktiviert die Kugel des Herausforderers und reinigt Auchindoun von der finsteren Präsenz Teron'gors.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Herausforderungsmodus von Auchindoun ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[37260] = { id = 37260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Gug'rokk", description = "{name}, Ihr müsst eine herausragende Gruppe zusammenstellen und sie in die Tiefen der Blutschlägerminen führen. Aktiviert die Kugel des Herausforderers und befreit die Minenarbeiter aus der tyrannischen Herrschaft von Gug'rokk.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Herausforderungsmodus der Blutschlägermine ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[37261] = { id = 37261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Himmelsfürstin Tovra", description = "{name}, Ihr müsst einen Elitetrupp zusammenstellen und das Grimmgleisdepot infiltrieren. Aktiviert die Kugel des Herausforderers, schlagt Euch zum Grimmgleis durch und bereitet der Luftunterstützung durch Himmelsfürstin Tovra ein Ende.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Herausforderungsmodus des Grimmgleisdepots ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[37262] = { id = 37262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Skullok, Sohn von Gruul", description = "{name}, Ihr müsst eine kühne Gruppe zusammenstellen und in die Eisendocks einbrechen. Aktiviert die Kugel des Herausforderers, zerstört die Ausbildungseinrichtung der Eisernen Horde und bereitet der Unterwerfung einer der mächtigsten Kreaturen von Draenor, Skullok, Sohn von Gruul, ein Ende.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Herausforderungsmodus der Eisendocks ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[37263] = { id = 37263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Ner'zhul", description = "{name}, Ihr müsst eine entschlossene Gruppe aus Kriegern zusammenstellen und sie in die Schattenmondgrabstätte führen. Aktiviert die Kugel des Herausforderers und unterbrecht Ner'zhuls Kommunion mit der Leere, bevor er ganz Draenor mit sich reißt.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Herausforderungsmodus der Schattenmondgrabstätte ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[37264] = { id = 37264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Oberste Weise Viryx", description = "{name}, Ihr müsst eine Gruppe unbeirrbarer Abenteurer zusammenstellen und sie zur Himmelsnadel führen. Aktiviert die Kugel des Herausforderers, steigt hinauf bis zum Gipfel und vernichtet die Oberste Weise Viryx und ihre Superwaffe.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Herausforderungsmodus der Himmelsnadel ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[37265] = { id = 37265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Yalnu", description = "{name}, Ihr müsst eine entschlossene Gruppe Abenteurer zusammenstellen und sie in den Immergrünen Flor führen. Aktiviert die Kugel des Herausforderers, dringt in die Tiefen des Immergrünen Flors vor und bereitet Yalnu und seinen Plänen ein Ende.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Herausforderungsmodus des Immergrünen Flors ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[37266] = { id = 37266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Kriegsfürstin Zaela", description = "{name}, Ihr müsst eine standhafte Gruppe Abenteurer zusammenstellen und zurück nach Azeroth zur Oberen Schwarzfelsspitze reisen. Aktiviert die Kugel des Herausforderers, betretet die alte Heimat des Schwarzfelsklans und besiegt die Vorhut des Eisernen Marsches und ihre neue Verbündete, Kriegsfürstin Zaela .\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Herausforderungsmodus der Oberen Schwarzfelsspitze ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[37270] = { id = 37270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alchemieexperiment", sourceObjective = "Ich führe heute wieder Experimente durch und ich habe ein paar Formeln für Tränke entwickelt, die Euch vielleicht dienlich sein könnten, Kommandant. Möchtet Ihr mal einen ausprobieren?", sourceObjectiveStatus = "unverified-source-field" }
quests[37271] = { id = 37271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Teron'gor", description = "{name}, Ihr müsst eine furchtlose Gruppe zusammenstellen und sie in die Tiefen von Auchindoun führen. Aktiviert die Kugel des Herausforderers und reinigt Auchindoun von der finsteren Präsenz Teron'gors.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Herausforderungsmodus von Auchindoun ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[37272] = { id = 37272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Gug'rokk", description = "{name}, Ihr müsst eine herausragende Gruppe zusammenstellen und sie in die Tiefen der Blutschlägerminen führen. Aktiviert die Kugel des Herausforderers und befreit die Minenarbeiter von Gug'rokks tyrannischer Herrschaft.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Herausforderungsmodus der Blutschlägermine ab.", sourceObjectiveStatus = "unverified-source-field" }
