quests[37274] = { id = 37274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Skullok, Sohn von Gruul", description = "{name}, Ihr müsst eine kühne Gruppe zusammenstellen und in die Eisendocks einbrechen. Aktiviert die Kugel des Herausforderers, zerstört die Ausbildungseinrichtung der Eisernen Horde und bereitet der Unterwerfung einer der mächtigsten Kreaturen von Draenor, Skullok, Sohn von Gruul, ein Ende.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Herausforderungsmodus der Eisendocks ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[37275] = { id = 37275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Ner'zhul", description = "{name}, ich brauche Eure Hilfe: Stellt eine Gruppe entschlossener Krieger bereit und führt sie in die Schattenmondgrabstätte. Aktiviert die Kugel des Herausforderers und haltet Ner'zhuls Verbindung mit der Leere auf, bevor er ganz Draenor in den Abgrund reißt.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung gemeistert habt und ich werde Euch großzügig entlohnen.", sourceObjective = "Schließt den Herausforderungsmodus der Schattenmondgrabstätte ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[37276] = { id = 37276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinsam stark", sourceObjective = "Die Zerschmetterte Hand und ihre Verbündeten sind gefährlich, Kommandant. Nichts für ungut, aber ich traue Euren stehenden Streitkräften nicht zu, einen möglichen Meuchelmörder davon abzuhalten, sich unbemerkt einzuschleichen.\n\nIch melde mich freiwillig, um Euren Streitkräften beizutreten, damit ich die Bewegungen des Feindes genau im Auge behalten kann. Wir können uns nicht leisten, dass Ihr einen frühzeitigen Tod erleidet. Dafür lastet zu viel auf Euren Schultern.", sourceObjectiveStatus = "unverified-source-field" }
quests[37277] = { id = 37277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Oberste Weise Viryx", description = "{name}, Ihr müsst eine Gruppe unbeirrbarer Abenteurer zusammenstellen und sie zur Himmelsnadel führen. Aktiviert die Kugel des Herausforderers, steigt hinauf bis zum Gipfel und vernichtet die Oberste Weise Viryx und ihre Superwaffe.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Herausforderungsmodus der Himmelsnadel ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[37278] = { id = 37278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Yalnu", description = "{name}, Ihr müsst eine entschlossene Gruppe Abenteurer zusammenstellen und sie in den Immergrünen Flor führen. Aktiviert die Kugel des Herausforderers, dringt in die Tiefen des Immergrünen Flors vor und setzt Yalnu und seinen Plänen ein Ende.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Herausforderungsmodus des Immergrünen Flors ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[37279] = { id = 37279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Herausforderung: Kriegsfürstin Zaela", description = "{name}, Ihr müsst eine standhafte Gruppe Abenteurer zusammenstellen und zurück nach Azeroth zur Oberen Schwarzfelsspitze reisen. Aktiviert die Kugel des Herausforderers, betretet die alte Heimat des Schwarzfelsklans und besiegt die Vorhut des Eisernen Marsches und ihre neue Verbündete, Kriegsfürstin Zaela.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Herausforderungsmodus der Oberen Schwarzfelsspitze ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[37280] = { id = 37280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fauchtatzenstieg" }
quests[37281] = { id = 37281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinsam stark", sourceObjective = "Nix für ungut, Kommandant, aber ich trau' Euren Truppen nich' zu, 'nen Anschlag der Zerschmetterten Hand auf Euer Leben zu verhindern.\n\nWenn's Euch nichts ausmacht, würd' ich gern Eurer Garnison beitreten un' die Halunken im Auge behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[37282] = { id = 37282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "COLISEUM WINNER FLAG (MONUMENT FLAG-NO RESET)" }
quests[37283] = { id = 37283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "COLISEUM LOSER FLAG (DAILY RESET)" }
quests[37284] = { id = 37284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fette Beute", description = "Ich weiß, ich weiß. Ich hab' sie Euch für Eure Schätze gegeben, aber nu will ich sie zurückhab'n. Das is' kompliziert, Mann. Wollt Ihr nu das Gold oder nich'?", sourceObjective = "Beschafft schäbige Eisenmünzen für Gaunah.", progress = "Also habt Ihr sie?", completion = "Oh, Ihr habt die für mich geholt? Klasse. Hier is' Euer Geld.", sourceObjectiveStatus = "unverified-source-field" }
quests[37285] = { id = 37285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Ihr sicher seid", description = "Ihr sammelt da 'ne Menge Schätze ein. Nächste Woche sin' die noch mehr wert, aber ich kann Sie Euch abnehmen.", sourceObjective = "Gebt Gaunah überflüssige schäbige Eisenmünzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[37286] = { id = 37286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blutvergießen nimmt kein Ende", description = "Ihr seid unersättlich, <Gladiator/Gladiatorin>! An Eurer Gier nach Zerstörung und Tod besteht kein Zweifel!\n\nKaiser Mar'gok wird sehr zufrieden sein, wenn er Euch erneut in der Arena des Kolosseums kämpfen sieht!\n\nWie zuvor werde ich nicht weniger als 100 Leben akzeptieren!\n\nTötet oder werdet getötet, <Gladiator/Gladiatorin>!", sourceObjective = "Tötet 100 Gladiatoren im Kolosseum von Hochfels.\n\nIhr erhaltet Zugang zum Kolosseum, wenn Ihr mit Kharg in Hochfels oder in der Knochenschlucht bei Eurem Heiligtum des Gladiators sprecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[37287] = { id = 37287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufräumarbeiten", description = "Vor nicht allzu langer Zeit is' hier 'n neuer Rekrut namens Jacob Anders aufgetaucht. Seit er hier is', hat er nichts als Ärger gemacht. Ständig trinkt er und fängt Prügeleien an, doch diesmal hat er den Bogen überspannt.\n\nEine unserer Patrouillen hat ihn geseh'n, wie er Informationen an die Horde verkauft hat. Er is'n Verräter, Kommandant! Ich dachte, Ihr würdet Euch gern selbst um ihn kümmern.\n\nDas letzte Mal, als ich ihn sah, war er unt'n am Wasser was trinken, und ich wette beim Barte meines Vaters, dass er immer noch dort is'.", sourceObjective = "Kümmert Euch um Jacob Anders in Südhafen.", completion = "Ich glaub', Ihr habt das Richtige getan, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[37288] = { id = 37288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ressourcen in Ashran", description = "Bodrick hat mir gegenüber erwähnt, dass Ihr während Eurer Beutezüge da draußen einige interessante Konstruktionsnotizen erlangt habt. Vielleicht eine Bauanleitung oder Aufbauhinweise?\n\nIhr solltet Euch mit Kinkade Jacobs am Sturmschild unterhalten. Vielleicht tauscht sie fertige Baupläne dafür ein.", sourceObjective = "Sprecht mit Kinkade Jacobs am Sturmschild in Ashran.", completion = "Oh, Ihr habt einige Texte zu Bauplänen für mich? Das ist großartig!\n\nLasst uns ins Geschäft kommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[37289] = { id = 37289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion des Schattenmondklans!", description = "Ihr hättet zu keinem besseren Zeitpunkt kommen können, Kommandant.\n\nRäuber des Schattenmondklans wurden beobachtet, wie sie sich der Garnison nähern.\n\nIhr habt ihren Vormarsch auf das Teluuna-Observatorium zurückgeschlagen und in Shaz'gul Chaos angerichtet.\n\nSie wollen sich bestimmt dafür rächen und werden alles gegen uns einsetzen, was ihnen zur Verfügung steht.\n\nIch habe die gesamte Garnison in höchste Alarmbereitschaft versetzt. Seid Ihr bereit, ihnen entgegenzutreten?", sourceObjective = "Schlagt die Invasion Eurer Garnison durch den Schattenmondklan zurück.\n\n(Sprecht erneut mit Unteroffizier Krähler, um zu beginnen.)", progress = "Es wird Zeit, ein wenig Licht in diese Schatten zu bringen!", completion = "Ich glaube nicht, dass sie darauf vorbereitet waren. Der Schattenmondklan wird es sich genau überlegen, bevor er uns wieder angreift.", sourceObjectiveStatus = "unverified-source-field" }
quests[37290] = { id = 37290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbesserungen in Ashran", description = "Habt Ihr Bauanleitungen oder Aufbauhinweise dabei? Oh Mann, das sind gute Neuigkeiten!\n\nIch kenne diesen Typen in Ashran, Torgg Flexington. Er hat die fertigen Baupläne, die wir brauchen!\n\nGeht, unterhaltet Euch mit ihm und bringt etwas Schönes mit, das wir bauen können, ja?", sourceObjective = "Sprecht mit Torgg Flexington beim Kriegsspeer in Ashran.", completion = "JAWOLLJA! Da lässt sich was machen. Ich habe eine Menge Zeug, das Ihr kaufen könnt!", sourceObjectiveStatus = "unverified-source-field" }
quests[37291] = { id = 37291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerfürsteninvasion!", description = "Ihr hättet keinen besseren Zeitpunkt wählen können.\n\nUnsere Späher haben gemeldet, dass sich eine große Donnerfürstenarmee nähert.\n\nMein Klan kann hinausreiten und dabei helfen, ihren Nachschub abzuschneiden, aber Ihr werdet Euch um die Verteidigung Eurer Festung gegen ihre Hauptstreitmacht kümmern müssen.\n\nUnteroffizier Grimmkinn erwartet Euren Befehl.", sourceObjective = "Schlagt die anrückenden Donnerfürsten zurück.", progress = "Die Frostwölfe sind bereit.", completion = "Gut gekämpft, Kommandant. Jetzt schlagt zurück, bevor der Donnerfürstenklan sich erholen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[37292] = { id = 37292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht in Eurer Armee", description = "Eure Männer haben 'ne neue Rekrutin dabei erwischt, wie sie hinter Eurem Rücken mit der Allianz gesproch'n hat. Sie is' 'ne Verräterin, <Scheff/Scheffin>! Sie gefährdet alles, wofür Ihr so hart geschuftet habt.\n\nEin Wyvern steht bereit, um sie zur passenden Bestrafung zu Eurer Garnison zu bringen. Ich dachte, Ihr würdet Euch gern selbst um die Kanaille kümmern.\n\nDas letzte Mal hab' ich sie auf der Nebenstraße gesehen, die aus Axtfall 'rausführt.", sourceObjective = "Kümmert Euch um Rorka in Axtfall.", completion = "Das is' die richtige Entscheidung, Kommandant. Für sowas gibt's in Eurer Truppe keinen Platz.", sourceObjectiveStatus = "unverified-source-field" }
quests[37293] = { id = 37293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Nebel lichten", description = "<Die Haut des Trolls wirkt blass. Schweißtropfen stehen auf seiner Stirn.>\n\nIch weiß, Ihr schuldet mir nix, aber wenn Ihr mir helfen wollt, gäb's 'nen Gefallen, den Ihr mir tun könnt.\n\nIm Norden is 'ne Kreatur, die diesen Giftnebel macht.\n\nNur das Herz von dem Biest kann die Gifte in meinem Körper neutralisieren.\n\nKann sein, dass Ihr 'n paar Krabbler töten müsst, wo Ihr schon dabei seid.\n\nWenn das Gift Euch schwächt, esst 'n paar von den leuchtenden Pilze, um seine Wirkung abzuschwächen.", sourceObjective = "Tötet 8 himmelblaue Krabbler und findet das überwucherte Herz.", progress = "Ich fühl' mich nich' so gut.", completion = "Ja! Das is' das Herz! Ihr habt's geschafft...", sourceObjectiveStatus = "unverified-source-field" }
quests[37294] = { id = 37294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "COLISEUM BOOBY PRIZE FLAG (DAILY RESET)" }
quests[37295] = { id = 37295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet Rylai Jammerthal" }
quests[37296] = { id = 37296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mangel an Wespen", description = "Ihre Stiche! Diese verfluchten Wespen summen tagaus, tagein und ihre ständige Aggression belastet mich schwer.\n\nIch werde mich erst dann um Euer Angebot kümmern, wenn jemand sich dieser Plagegeister angenommen hat.", sourceObjective = "Tötet 8 Witwenwespen.", completion = "Vielleicht kann ich meine Rituale zumindest für ein paar Nächte ungestört durchführen. Euer Angebot klingt vielversprechend und ich glaube, dass wir zu einer Übereinkunft kommen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[37297] = { id = 37297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet Jeron Funkendrift" }
quests[37298] = { id = 37298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonusziel: Tötet Priester des Kriegsspeers" }
