quests[37317] = { id = 37317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talon King Ikiss" }
quests[37318] = { id = 37318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Toten vergessen nie...", description = "Vor vielen Jahren wurden meine Familie und ich genau hier ermordet.\n\nDie Saberon, die Ihr hier seht, stammen von dem Stamm ab, der mein Dorf abgeschlachtet hat. Ich habe so lange an diesem verlassenen Ort ausgeharrt, um zu sehen, dass die Saberon für ihre Gräueltaten büßen müssen.\n\nDer Häuptling der Fauchtatzen ist ein Knochenseher – ein Saberon, der die Zukunft mithilfe der Überreste der Toten vorhersagen kann.\n\nSammelt die uralten Schädel der Fauchtatzenahnen und werft sie in den Kessel des Knochensehers.\n\nDieses eine Mal sollen ihre eigenen Knochen den Kessel füllen!", sourceObjective = "Werft 10 uralte Fauchtatzenschädel in den Kessel des Knochensehers.", progress = "<Im Kessel brodelt es gewaltig.>", completion = "<Mit jedem Schädel, den Ihr in den brodelnden Kessel werft, wird kochende Flüssigkeit herausgeschleudert.>\n\n<Als der letzte Schädel im brodelnden Kessel versinkt, spürt Ihr deutlich, wie ein geisterhafter Hauch Euch streift.>", sourceObjectiveStatus = "unverified-source-field" }
quests[37319] = { id = 37319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonderauftrag für Juwelierskunst: Eheringe", description = "Wir wurden gebeten, ein Paar Eheringe anzufertigen. Die Kunden haben darauf bestanden, dass Ihr diese Arbeit übernehmt.", sourceObjective = "Stellt zwei leuchtende Schwarzfelsbänder her. Die Sekundärwerte sind dabei nicht ausschlaggebend.", progress = "Möchtet Ihr die Bestellung übernehmen? Wir können die Arbeit natürlich ablehnen, aber das ist ein gutes Angebot.", completion = "Die sind wirklich wunderschön. Braut und Bräutigam werden begeistert sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[37320] = { id = 37320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonderauftrag für Juwelierskunst: Ein edler Halsreif", description = "Wir haben eine Anfrage nach einem edlen Halsschmuck. Die Kundin möchte ihn einer alten Feindin schenken, um einen seit Ewigkeiten währenden Streit beizulegen. Sie hat sich nicht zum Aussehen geäußert, dafür aber etwas über einen \"Halsreif\" gemurmelt.\n\nOh, und sie sagte, dass die Kette \"schön robust\" sein solle.", sourceObjective = "Stellt einen flüsternden Eisenhalsreif her. Die Sekundärwerte sind dabei nicht ausschlaggebend.", progress = "Möchtet Ihr die Bestellung übernehmen? Wir können die Arbeit natürlich ablehnen, aber das ist ein gutes Angebot.", completion = "Wunderschön. Die Kundin hat gerade eben noch gesagt, dass sie es kaum erwarten könne, ihn ihrer Rivalin umzulegen. Dank dieses Geschenks wird es sicher keinen weiteren Streit mehr geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[37321] = { id = 37321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonderauftrag für Juwelierskunst: Goldener als Gold", description = "Wir wurden damit beauftragt, ein Goldarmband mit einem Taladitkristall anzufertigen, der \"heller als Gold scheint\". Ich kann mich um die Metallarbeiten kümmern, aber mit dem Kristall kann ich nicht umgehen.", sourceObjective = "Stellt einen Taladiten mit dem Bonus 'Kritischer Trefferwert' her.", progress = "Möchtet Ihr die Bestellung übernehmen? Wir können die Arbeit natürlich ablehnen, aber das ist ein gutes Angebot.", completion = "Es ist wunderschön.", sourceObjectiveStatus = "unverified-source-field" }
quests[37322] = { id = 37322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Botschaft des Propheten", description = "Dieser unscheinbar schimmernde Kristall enthält einige der letzten Gedanken des großen Propheten Velen und wurde in den letzten Stunden vor seinem Kampf mit Ner'zhul hergestellt.\n\nBringt den Kristall zum Denkmal des Propheten Velen unterhalb des Kolosseums des Lichts nahe Karabor, um seine letzte Botschaft zu hören.", sourceObjective = "Bringt das Arkanum des Propheten zum Denkmal des Propheten Velen unterhalb des Kolosseums des Lichts im Schattenmondtal.", progress = "Das Arkanum summt in Eurer Hand, während Ihr Euch der Gedenkstätte nähert.", completion = "Der Schrein weist Dutzende Nischen auf, in denen die Anhänger des Propheten ihre eigenen Speicherkristalle platziert haben, um das Opfer ihres großen Anführers zu betrauern. Als Ihr den Kristall in einer leeren Öffnung platziert, erwacht das Denkmal zum Leben...", sourceObjectiveStatus = "unverified-source-field" }
quests[37323] = { id = 37323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonderauftrag für Juwelierskunst: Blau wie der Himmel und das Meer", description = "Die Kundin möchte ein paar Silberohrringe mit blauen Kristallen, die zu ihrer Augenfarbe passen. Die Metallarbeiten sind kein Problem, aber ich weiß nicht, wie man Taladiten mit einer solchen Farbgebung herstellt.", sourceObjective = "Stellt zwei Taladiten mit dem Bonus 'Tempo' her.", progress = "Möchtet Ihr die Bestellung übernehmen? Wir können die Arbeit natürlich ablehnen, aber das ist ein gutes Angebot.", completion = "Die sind perfekt. Ich bin fast geneigt zu glauben, dass meine Metallarbeiten diesen Edelsteinen nicht gerecht werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[37324] = { id = 37324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mehr auf Lager: Schwarzfelserz", description = "Unser neuestes Armbandmodell verkauft sich wie verrückt. Aber wir haben kein Schwarzfelserz mehr, um weitere davon herzustellen.", sourceObjective = "Beschafft zwanzig Einheiten Schwarzfelserz.", progress = "Wenn wir nicht mehr Schwarzfelserz bekommen, werden wir die Bestellungen nicht erfüllen können.", completion = "Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[37325] = { id = 37325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mehr auf Lager: Echteisenerz", description = "Unsere kleine Schleiferei scheint sich langsam einen guten Namen zu machen. Wir verwenden Echteisen für all unsere Modelle, und wisst Ihr was? Es ist uns ausgegangen!", sourceObjective = "Beschafft zwanzig Einheiten Echteisenerz.", progress = "Wir können uns glücklich schätzen, dass unsere Juweliersarbeiten so gefragt sind. Aber ohne weiteres Echteisen können wir keine weiteren Stücke anfertigen.", completion = "Jetzt können wir wieder loslegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[37326] = { id = 37326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freundschaft mit den Einheimischen schließen", description = "Wir brauchen ganz dringend Verbündete, wenn wir auch nur den nächsten Tag überleben wollen. Wir haben Kontakt mit einem ausgestoßenen Arakkoa aufgenommen, aber er weigert sich, über Bündnisse zu verhandeln, ohne zuvor mit Euch gesprochen zu haben.\n\nEr nennt sich selbst Dämmerungsweiser Irizzar. Ihr solltet mit ihm sprechen, Kommandant.\n\nIhr findet ihn gleich südwestlich des Terokkverstecks.", sourceObjective = "Sprecht mit dem Dämmerungsweisen Irizzar nahe des Terokkverstecks.", completion = "Ah, Ihr seid also derjenige, von dem Eure Leute mit so viel Hochachtung gesprochen haben. Wir können über ein Bündnis verhandeln, aber zuvor...", sourceObjectiveStatus = "unverified-source-field" }
quests[37327] = { id = 37327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freundschaft mit den Einheimischen schließen", description = "Kommandant, ich glaube, im Sinne der Sicherheit dieses Außenpostens sollten wir um die Hilfe eines Verbündeten ersuchen. Wir haben Kontakt mit einem ausgestoßenen Arakkoa aufgenommen, aber er weigert sich, ein Bündnis in Aussicht zu stellen, ohne zuvor mit Euch gesprochen zu haben.\n\nEr nennt sich selbst Dämmerungsweiser Irizzar. Könntet Ihr vielleicht mit ihm sprechen, Kommandant?\n\nIhr findet ihn gleich südwestlich des Terokkverstecks.", sourceObjective = "Sprecht mit dem Dämmerungsweisen Irizzar nahe des Terokkverstecks.", completion = "Ah, Ihr seid also derjenige, von dem Eure Leute mit so viel Hochachtung gesprochen haben. Wir können über ein Bündnis verhandeln, aber zuvor...", sourceObjectiveStatus = "unverified-source-field" }
quests[37328] = { id = 37328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht hier. Nicht jetzt.", description = "Ich werde schon bald Eure Leute aufsuchen, um die Vereinbarungen zu verhandeln.\n\nUnd jetzt entfernt Euch. Lasst mich in Ruhe.", sourceObjective = "Sprecht mit Zuchtmeister Gornek in Axtfall.", completion = "Ausgezeichnet. Wir haben dringendere Angelegenheiten, um die wir uns kümmern müssen, bevor er herkommt.\n\nDie Dunkle Waldläuferin Velonara benötigt Eure sofortige Unterstützung, werter Herr.", sourceObjectiveStatus = "unverified-source-field" }
quests[37329] = { id = 37329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht hier. Nicht jetzt.", description = "Ich werde schon bald Eure Leute aufsuchen, um die Vereinbarungen zu verhandeln.\n\nUnd jetzt entfernt Euch. Lasst mich in Ruhe.", sourceObjective = "Sprecht mit Leutnant Willem in Südhafen.", completion = "Ausgezeichnet. Wir haben dringendere Angelegenheiten, um die wir uns kümmern müssen, bevor er herkommt.\n\nHulda Schattenklinge benötigt Eure sofortige Unterstützung, werter Herr.", sourceObjectiveStatus = "unverified-source-field" }
quests[37330] = { id = 37330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht hier. Nicht jetzt.", description = "Ich werde schon bald Eure Leute aufsuchen, um die Vereinbarungen zu verhandeln.\n\nUnd jetzt entfernt Euch. Lasst mich in Ruhe.", sourceObjective = "Sprecht mit Zuchtmeister Gornek in Axtfall.", completion = "Gut gemacht, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[37331] = { id = 37331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht hier. Nicht jetzt.", description = "Ich werde schon bald Eure Leute aufsuchen, um die Vereinbarungen zu verhandeln.\n\nUnd jetzt entfernt Euch. Lasst mich in Ruhe.", sourceObjective = "Sprecht mit Leutnant Willem in Südhafen.", completion = "Gut gemacht, werter Herr.", sourceObjectiveStatus = "unverified-source-field" }
quests[37332] = { id = 37332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilzklumpen", description = "Der Umbrasporenriese, den Ihr getötet habt, scheint gegen die flüchtigen Sporen in dieser Gegend immun gewesen zu sein. Vielleicht sind die über seinen ganzen Körper verteilten seltsamen Geschwulste der Grund für diese Immunität. Schnappt Euch einen dieser widerlichen Pilzklumpen und bringt ihn zu der Rangari, damit sie ihn untersuchen kann.", sourceObjective = "Bringt das seltsame Geschwulst zu Rangari Sheera in der Enklave der Rangari im Schattenmondtal.", progress = "Was habt Ihr gefunden, {class}?", completion = "Oh! Ihr wurdet von einem Umbrasporenriesen angegriffen? Die sind sehr gefährlich. Ihr wart wirklich mutig, gegen ihn zu kämpfen!\n\nDieses Geschwulst, das Ihr gefunden habt, scheint kein Teil dieses Riesen zu sein. Vielmehr scheint es sich dabei um eine symbiotische Lebensform zu handeln. Wir müssen sie weiter erforschen, um herauszufinden, welchen Vorteil der Wirt daraus bezieht.\n\nIch danke Euch, {name}. Das war wirklich hervorragende Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
